			t.Details = map[string]interface{}{}
		}
		timeline = append(timeline, t)
	}
	return timeline, nil
}

// ── Deactivate/Activate ──

func (s *Service) DeactivateEntity(db_ *sql.DB, entityType, entityID string) error {
	switch entityType {
	case "location":
		_, err := db_.Exec(`UPDATE locations SET active = FALSE WHERE location_id = $1`, entityID)
		return err
	case "connection":
		_, err := db_.Exec(`UPDATE connections SET active = FALSE WHERE connection_id = $1`, entityID)
		return err
	case "user":
		_, err := db_.Exec(`UPDATE users SET active = FALSE WHERE user_id = $1`, entityID)
		return err
	default:
		return fmt.Errorf("unknown entity type: %s", entityType)
	}
}

func (s *Service) ActivateEntity(db_ *sql.DB, entityType, entityID string) error {
	switch entityType {
	case "location":
		_, err := db_.Exec(`UPDATE locations SET active = TRUE WHERE location_id = $1`, entityID)
		return err
	case "connection":
		_, err := db_.Exec(`UPDATE connections SET active = TRUE WHERE connection_id = $1`, entityID)
		return err
	case "user":
		_, err := db_.Exec(`UPDATE users SET active = TRUE WHERE user_id = $1`, entityID)
		return err
