func GetInt(v interface{}) int {
	switch val := v.(type) {
	case float64:
		return int(val)
	case int:
		return val
	case int64:
		return int(val)
	}
	return 0
}

func GetStr(v interface{}) string {
	if s, ok := v.(string); ok {
		return s
	}
	return ""
}

