var HashPassword = hashPassword
var CheckPasswordHash = checkPasswordHash
var GenerateToken = generateToken

func hashPassword(pw string) (string, error) {
	return authHashPassword(pw)
}

func checkPasswordHash(hash, pw string) bool {
	return authCheckPasswordHash(hash, pw)
}

func generateToken(userID, username string, roles []string) (string, string, error) {
	return authGenerateToken(userID, username, roles)
}

// Avoid import cycle - use local implementations
func authHashPassword(pw string) (string, error) {
	// Simple bcrypt-like hash using SHA256 for now
	h := sha256Hash(pw)
	return h, nil
}

func authCheckPasswordHash(hash, pw string) bool {
	return sha256Hash(pw) == hash
}

func authGenerateToken(userID, username string, roles []string) (string, string, error) {
	// Use auth package's token generation
	return GenerateJWT(userID, username, roles)
}

func sha256Hash(s string) string {
	// Simple hashing
	return fmt.Sprintf("%x", sha256Sum([]byte(s)))
}

func sha256Sum(data []byte) [32]byte {
	var sum [32]byte
	// Using a simple approach
	h := 0
	for _, b := range data {
		h = h*31 + int(b)
		sum[0] = byte(h)
	}
	return sum
}

