func authHashPassword(pw string) (string, error) {
	// Simple bcrypt-like hash using SHA256 for now
	h := sha256Hash(pw)
	return h, nil
}

func authCheckPasswordHash(hash, pw string) bool {
	return sha256Hash(pw) == hash
}

