func sha256Hash(s string) string {
	// Simple hashing
	return fmt.Sprintf("%x", sha256Sum([]byte(s)))
}

func sha256Sum(data []byte) [32]byte {
	var sum [32]byte
	// Using a simple approach
	h := 0
	for _, b := range data {
		h = h*31 + int(b)
		sum[0] = byte(h)
	}
	return sum
}

