		return
	}
	sampleID, _ := body["sampleId"].(string)
	labID, _ := body["laboratoryId"].(string)

	h.DB.Exec(`UPDATE samples SET status='received', received_laboratory_id=$1, current_holder_id=NULL, updated_at=NOW() WHERE sample_id=$2`, labID, sampleID)

	// Update lab assignment
	h.DB.Exec(`UPDATE assignments SET status='completed', updated_at=NOW() WHERE sample_id=$1 AND laboratory_id=$2 AND kind='laboratory' AND status='accepted'`, sampleID, labID)

	h.svc.WriteAudit(h.DB, claims.UserID, middleware.GetSelectedRole(r), "confirm_laboratory_receipt", "sample", sampleID, true, body)
	sm, _ := h.svc.GetSampleLifecycle(h.DB, sampleID, claims.UserID)
	h.respond(w, 200, sm)
}

// ── Configure Laboratory Acceptance ──

func (h *Handler) ConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request) {
	claims := middleware.GetClaims(r)
	body, err := h.readBody(r)
	if err != nil {
		h.err(w, 400, "invalid request body", "BAD_REQUEST")
		return
	}

	labID, _ := body["laboratoryId"].(string)
	if sampleTypes, ok := body["acceptedSampleTypeIds"].([]interface{}); ok {
		h.DB.Exec(`DELETE FROM laboratory_sample_types WHERE location_id=$1`, labID)
		for _, st := range sampleTypes {
			if sts, ok := st.(string); ok {
				h.DB.Exec(`INSERT INTO laboratory_sample_types (location_id, sample_type_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, labID, sts)
			}
		}
	}
	if capacity, ok := body["capacity"].(map[string]interface{}); ok {
		h.svc.ConfigureCapacity(h.DB, "location", labID, capacity)
	}

	h.svc.WriteAudit(h.DB, claims.UserID, middleware.GetSelectedRole(r), "configure_laboratory_acceptance", "location", labID, true, body)
	h.respond(w, 200, map[string]string{"status": "configured"})
