}

func (h *Handler) GetSampleTypes(w http.ResponseWriter, r *http.Request) {
	rows, err := h.DB.Query(`SELECT sample_type_id FROM sample_types`)
	if err != nil {
		h.err(w, 500, err.Error(), "INTERNAL")
