observation.old_content:
package handler

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"strings"

	"lab-sample-system/internal/middleware"
	"lab-sample-system/internal/model"
	"lab-sample-system/internal/service"
)

type Handler struct {
	svc *service.Service
	DB  *sql.DB
}

func New(svc *service.Service, db *sql.DB) *Handler {
	return &Handler{svc: svc, DB: db}
}

func (h *Handler) respond(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if data != nil {
		json.NewEncoder(w).Encode(model.APIResponse{Data: data})
	}
}

func (h *Handler) err(w http.ResponseWriter, status int, msg, code string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(model.ErrorResponse{Error: msg, Code: code})
}

func (h *Handler) readBody(r *http.Request) (map[string]interface{}, error) {
	var body map[string]interface{}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		return nil, err
	}
	return body, nil
}

// ── Auth ──

func (h *Handler) Login(w http.ResponseWriter, r *http.Request) {
	body, err := h.readBody(r)
	if err != nil {
		h.err(w, 400, "invalid request body", "BAD_REQUEST")
		return
	}
	username, _ := body["username"].(string)
	password, _ := body["password"].(string)
	if username == "" || password == "" {
		h.err(w, 400, "username and password required", "BAD_REQUEST")
		return
	}

	resp, apiErr := h.svc.Authenticate(h.DB, username, password)
	if apiErr != nil {
		code := 401
		if apiErr.Code == "FORBIDDEN" {
			code = 403
		}
		h.err(w, code, apiErr.Error, apiErr.Code)
		return
	}
	h.svc.WriteAudit(h.DB, resp.UserID, "any", "login", "user", resp.UserID, true, nil)
	h.respond(w, 200, resp)
}

func (h *Handler) Logout(w http.ResponseWriter, r *http.Request) {
	claims := middleware.GetClaims(r)
	if claims == nil {
		h.err(w, 401, "unauthorized", "UNAUTHORIZED")
		return
	}
	// Add JTI to blacklist
	h.DB.Exec(`INSERT INTO jwti_blacklist (jti, expires_at) VALUES ($1, $2) ON CONFLICT DO NOTHING`, claims.ID, claims.ExpiresAt.Time)
	h.svc.WriteAudit(h.DB, claims.UserID, "any", "logout", "user", claims.UserID, true, nil)
	h.respond(w, 200, map[string]string{"status": "logged_out"})
}

// ── Users ──

func (h *Handler) CreateUser(w http.ResponseWriter, r *http.Request) {
	body, err := h.readBody(r)
	if err != nil {
		h.err(w, 400, "invalid request body", "BAD_REQUEST")
		return
	}
	user, err := h.svc.CreateUser(h.DB, body)
	if err != nil {
		h.err(w, 500, err.Error(), "INTERNAL")
		return
	}
	claims := middleware.GetClaims(r)
	h.svc.WriteAudit(h.DB, claims.UserID, "administrator", "create_user", "user", user.UserID, true, map[string]interface{}{"username": user.Username})
	h.respond(w, 201, user)
}

func (h *Handler) GetUsers(w http.ResponseWriter, r *http.Request) {
	rows, err := h.DB.Query(`SELECT user_id FROM users ORDER BY username`)
	if err != nil {
		h.err(w, 500, err.Error(), "INTERNAL")
		return
	}
	defer rows.Close()

	var users []model.User
	for rows.Next() {
		var id string
		rows.Scan(&id)
		u, err := h.svc.GetUser(h.DB, id)
		if err == nil {
			users = append(users, *u)
		}
	}
	if users == nil {
		users = []model.User{}
	}
	h.respond(w, 200, users)
}

func (h *Handler) GetUser(w http.ResponseWriter, r *http.Request) {
	userID := r.PathValue("userId")
	user, err := h.svc.GetUser(h.DB, userID)
	if err != nil {
		h.err(w, 404, "user not found", "NOT_FOUND")
		return
	}
	h.respond(w, 200, user)
}

func (h *Handler) UpdateUser(w http.ResponseWriter, r *http.Request) {
	userID := r.PathValue("userId")
	body, err := h.readBody(r)
	if err != nil {
		h.err(w, 400, "invalid request body", "BAD_REQUEST")
		return
	}

	if locID, ok := body["assignedLocationId"].(string); ok {
		h.DB.Exec(`UPDATE users SET assigned_location_id=$1 WHERE user_id=$2`, locID, userID)
	}
	if active, ok := body["active"].(bool); ok {
		h.DB.Exec(`UPDATE users SET active=$1 WHERE user_id=$2`, active, userID)
	}
	if fullName, ok := body["fullName"].(string); ok {
		h.DB.Exec(`UPDATE users SET full_name=$1 WHERE user_id=$2`, fullName, userID)
	}
	if roles, ok := body["roles"].([]interface{}); ok {
		h.DB.Exec(`DELETE FROM user_roles WHERE user_id=$1`, userID)
		for _, r := range roles {
			if rs, ok := r.(string); ok {
				h.DB.Exec(`INSERT INTO user_roles (user_id, role) VALUES ($1, $2) ON CONFLICT DO NOTHING`, userID, rs)
			}
		}
	}
	if certs, ok := body["certifications"].([]interface{}); ok {
		h.DB.Exec(`DELETE FROM user_certifications WHERE user_id=$1`, userID)
		for _, c := range certs {
			if cm, ok := c.(map[string]interface{}); ok {
				code, _ := cm["code"].(string)
				active, _ := cm["active"].(bool)
				if code != "" {
					h.DB.Exec(`INSERT INTO user_certifications (user_id, code, active) VALUES ($1, $2, $3) ON CONFLICT (user_id, code) DO UPDATE SET active=$3`, userID, code, active)
				}
			}
		}
	}

	user, err := h.svc.GetUser(h.DB, userID)
	if err != nil {
		h.err(w, 404, "user not found", "NOT_FOUND")
		return
	}
	claims := middleware.GetClaims(r)
	h.svc.WriteAudit(h.DB, claims.UserID, "administrator", "update_user", "user", userID, true, nil)
	h.respond(w, 200, user)
}

// ── Locations ──

func (h *Handler) CreateLocation(w http.ResponseWriter, r *http.Request) {
	body, err := h.readBody(r)
	if err != nil {
		h.err(w, 400, "invalid request body", "BAD_REQUEST")
		return
	}
	loc, err := h.svc.CreateLocation(h.DB, body)
	if err != nil {
		h.err(w, 409, err.Error(), "CONFLICT")
		return
	}
	claims := middleware.GetClaims(r)
	h.svc.WriteAudit(h.DB, claims.UserID, "administrator", "create_location", "location", loc.LocationID, true, nil)
	h.respond(w, 201, loc)
}

func (h *Handler) GetLocations(w http.ResponseWriter, r *http.Request) {
	locs, err := h.svc.GetLocations(h.DB)
	if err != nil {
		h.err(w, 500, err.Error(), "INTERNAL")
		return
	}
	h.respond(w, 200, locs)
}

func (h *Handler) GetLocation(w http.ResponseWriter, r *http.Request) {
	locID := r.PathValue("locationId")
	loc, err := h.svc.GetLocation(h.DB, locID)
	if err != nil {
		h.err(w, 404, "location not found", "NOT_FOUND")
		return
	}
	locs := []model.Location{*loc}
	h.respond(w, 200, locs)
}

func (h *Handler) UpdateLocation(w http.ResponseWriter, r *http.Request) {
	locID := r.PathValue("locationId")
	body, err := h.readBody(r)
	if err != nil {
		h.err(w, 400, "invalid request body", "BAD_REQUEST")
		return
	}

	if name, ok := body["name"].(string); ok {
		h.DB.Exec(`UPDATE locations SET name=$1 WHERE location_id=$2`, name, locID)
	}
	if active, ok := body["active"].(bool); ok {
		h.DB.Exec(`UPDATE locations SET active=$1 WHERE location_id=$2`, active, locID)
	}
	if coord, ok := body["coordinate"].(map[string]interface{}); ok {
		if lat, ok := coord["latitude"].(float64); ok {
			if lng, ok := coord["longitude"].(float64); ok {
				h.DB.Exec(`UPDATE locations SET latitude=$1, longitude=$2 WHERE location_id=$3`, lat, lng, locID)
			}
		}
	}
	if funcs, ok := body["functions"].(map[string]interface{}); ok {
		for _, key := range []string{"collection_point", "transfer_point", "hub", "laboratory"} {
			if v, ok := funcs[key].(bool); ok {
				h.DB.Exec(`UPDATE locations SET fn_`+key+`=$1 WHERE location_id=$2`, v, locID)
			}
		}
	}
	if capacity, ok := body["capacity"].(map[string]interface{}); ok {
		h.svc.ConfigureCapacity(h.DB, "location", locID, capacity)
	}
	if stIDs, ok := body["acceptedSampleTypeIds"].([]interface{}); ok {
		h.DB.Exec(`DELETE FROM laboratory_sample_types WHERE location_id=$1`, locID)
		for _, st := range stIDs {
			if sts, ok := st.(string); ok {
				h.DB.Exec(`INSERT INTO laboratory_sample_types (location_id, sample_type_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, locID, sts)
			}
		}
	}

	loc, err := h.svc.GetLocation(h.DB, locID)
	if err != nil {
		h.err(w, 404, "location not found", "NOT_FOUND")
		return
	}
	claims := middleware.GetClaims(r)
	h.svc.WriteAudit(h.DB, claims.UserID, "administrator", "update_location", "location", locID, true, nil)
	h.respond(w, 200, loc)
}

// ── Connections ──

func (h *Handler) CreateConnection(w http.ResponseWriter, r *http.Request) {
	body, err := h.readBody(r)
	if err != nil {
		h.err(w, 400, "invalid request body", "BAD_REQUEST")
		return
	}
	conn, err := h.svc.CreateConnection(h.DB, body)
	if err != nil {
		h.err(w, 409, err.Error(), "CONFLICT")
		return
	}
	claims := middleware.GetClaims(r)
	h.svc.WriteAudit(h.DB, claims.UserID, "administrator", "create_connection", "connection", conn.ConnectionID, true, nil)
	h.respond(w, 201, conn)
}

func (h *Handler) GetConnections(w http.ResponseWriter, r *http.Request) {
	conns, err := h.svc.GetConnections(h.DB)
	if err != nil {
		h.err(w, 500, err.Error(), "INTERNAL")
		return
	}
	h.respond(w, 200, conns)
}

func (h *Handler) GetConnection(w http.ResponseWriter, r *http.Request) {
	connID := r.PathValue("connectionId")
