	labID, _ := body["laboratoryId"].(string)
	if sampleTypes, ok := body["acceptedSampleTypeIds"].([]interface{}); ok {
		h.DB.Exec(`DELETE FROM laboratory_sample_types WHERE location_id=$1`, labID)
		for _, st := range sampleTypes {
			if sts, ok := st.(string); ok {
				h.DB.Exec(`INSERT INTO laboratory_sample_types (location_id, sample_type_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, labID, sts)
			}
		}
	}
	if capacity, ok := body["capacity"].(map[string]interface{}); ok {
		h.svc.ConfigureCapacity(h.DB, "location", labID, capacity)
	}

	h.svc.WriteAudit(h.DB, claims.UserID, middleware.GetSelectedRole(r), "configure_laboratory_acceptance", "location", labID, true, body)
	h.respond(w, 200, map[string]string{"status": "configured"})
