// ── Role-based Work ──

func (h *Handler) GetRoleWork(w http.ResponseWriter, r *http.Request) {
	claims := middleware.GetClaims(r)
	role := middleware.GetSelectedRole(r)
	if role == "" && len(claims.Roles) > 0 {
		role = claims.Roles[0]
	}

	work := model.RoleWork{
		Pending:    []model.RoleWorkItem{},
		InProgress: []model.RoleWorkItem{},
		Completed:  []model.RoleWorkItem{},
	}

	switch role {
	case "requester":
		rows, _ := h.DB.Query(`SELECT sample_id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, claims.UserID)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var id string
				rows.Scan(&id)
				wi := h.sampleToWorkItem(h.DB, id, claims)
				if wi != nil {
					work.Pending = append(work.Pending, *wi)
				}
			}
		}
	case "collection_professional":
		// Assignments for collection
		aRows, _ := h.DB.Query(`SELECT assignment_id FROM assignments WHERE worker_id=$1 AND kind='collection' ORDER BY created_at DESC`, claims.UserID)
		if aRows != nil {
			defer aRows.Close()
			for aRows.Next() {
				var aid string
				aRows.Scan(&aid)
				wi := h.assignmentToWorkItem(h.DB, aid, claims)
				if wi != nil {
					if wi.Status == "completed" || wi.Status == "declined" || wi.Status == "cancelled" {
						work.Completed = append(work.Completed, *wi)
					} else if wi.Status == "in_progress" || wi.Status == "accepted" {
						work.InProgress = append(work.InProgress, *wi)
					} else {
						work.Pending = append(work.Pending, *wi)
					}
				}
			}
		}
	case "delivery_partner":
		aRows, _ := h.DB.Query(`SELECT assignment_id FROM assignments WHERE worker_id=$1 AND kind='transport' ORDER BY created_at DESC`, claims.UserID)
		if aRows != nil {
			defer aRows.Close()
			for aRows.Next() {
				var aid string
				aRows.Scan(&aid)
				wi := h.assignmentToWorkItem(h.DB, aid, claims)
				if wi != nil {
					if wi.Status == "completed" || wi.Status == "declined" || wi.Status == "cancelled" {
						work.Completed = append(work.Completed, *wi)
					} else if wi.Status == "in_progress" || wi.Status == "accepted" {
						work.InProgress = append(work.InProgress, *wi)
					} else {
						work.Pending = append(work.Pending, *wi)
					}
				}
			}
		}
	case "node_handler":
		aRows, _ := h.DB.Query(`SELECT assignment_id FROM assignments WHERE worker_id=$1 AND kind='node' ORDER BY created_at DESC`, claims.UserID)
		if aRows != nil {
			defer aRows.Close()
			for aRows.Next() {
				var aid string
				aRows.Scan(&aid)
				wi := h.assignmentToWorkItem(h.DB, aid, claims)
				if wi != nil {
					if wi.Status == "completed" || wi.Status == "declined" || wi.Status == "cancelled" {
						work.Completed = append(work.Completed, *wi)
					} else if wi.Status == "in_progress" || wi.Status == "accepted" {
						work.InProgress = append(work.InProgress, *wi)
					} else {
						work.Pending = append(work.Pending, *wi)
					}
				}
			}
		}
	case "laboratory_team":
		aRows, _ := h.DB.Query(`SELECT assignment_id FROM assignments WHERE worker_id=$1 AND kind='laboratory' ORDER BY created_at DESC`, claims.UserID)
		if aRows != nil {
			defer aRows.Close()
			for aRows.Next() {
				var aid string
				aRows.Scan(&aid)
				wi := h.assignmentToWorkItem(h.DB, aid, claims)
				if wi != nil {
					if wi.Status == "completed" || wi.Status == "declined" || wi.Status == "cancelled" {
						work.Completed = append(work.Completed, *wi)
					} else if wi.Status == "in_progress" || wi.Status == "accepted" {
						work.InProgress = append(work.InProgress, *wi)
					} else {
						work.Pending = append(work.Pending, *wi)
					}
				}
			}
		}
	case "dispatcher", "administrator":
		// All active samples and journeys
		sRows, _ := h.DB.Query(`SELECT sample_id FROM samples ORDER BY created_at DESC LIMIT 50`)
		if sRows != nil {
			defer sRows.Close()
			for sRows.Next() {
				var id string
				sRows.Scan(&id)
				wi := h.sampleToWorkItem(h.DB, id, claims)
				if wi != nil {
					work.Pending = append(work.Pending, *wi)
				}
			}
		}
	}

	h.respond(w, 200, work)
}

func (h *Handler) sampleToWorkItem(database *sql.DB, sampleID string, claims *auth.Claims) *model.SampleWorkItem {
	s := model.SampleWorkItem{Kind: "sample", SampleID: sampleID}
	var reqID, status, stID, originType, serv string
	var originNodeID, curHolderID, journeyID, labID sql.NullString
	var reqAt, deadline, earliest, latest, locRec sql.NullTime
	var lat, lng sql.NullFloat64

	err := database.QueryRow(`SELECT request_id, requester_id, status, sample_type_id, origin_type, origin_node_id,
		requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
		serviceability, current_holder_id, active_journey_id, target_laboratory_id,
		latitude, longitude, location_recorded_at
		FROM samples WHERE sample_id=$1`, sampleID).Scan(
		&reqID, &s.RequesterID, &status, &stID, &originType, &originNodeID,
		&reqAt, &deadline, &earliest, &latest,
		&serv, &curHolderID, &journeyID, &labID,
		&lat, &lng, &locRec)

	if err != nil {
		return nil
	}

	s.RequestID = reqID
	s.Status = status
	s.Serviceability = serv
	if reqAt.Valid {
		s.RequestedAt = &reqAt.Time
	}
	if deadline.Valid {
		s.DeliveryDeadline = &deadline.Time
	}
	if earliest.Valid {
		s.EarliestCollectionAt = &earliest.Time
	}
	if latest.Valid {
		s.LatestCollectionAt = &latest.Time
	}
	if journeyID.Valid {
		s.ActiveJourneyID = &journeyID.String
	}
	if labID.Valid {
		s.LaboratoryID = &labID.String
	}
	if curHolderID.Valid {
		s.CurrentHolderID = &curHolderID.String
	}
	if locRec.Valid {
		s.LocationRecordedAt = &locRec.Time
		s.LocationStale = time.Since(locRec.Time) > 15*time.Minute
	}

	timeline, _ := h.svc.GetTimeline(database, sampleID)
	s.History = timeline

	return &s
}

func (h *Handler) assignmentToWorkItem(database *sql.DB, assignmentID string, claims *auth.Claims) *model.AssignmentWorkItem {
	wi := model.AssignmentWorkItem{Kind: "assignment", AssignmentID: assignmentID}
	var kind, sampleID, status string
	var seq int
	var jid, workerID, fromLoc, toLoc, nodeID, labID sql.NullString
	var offerExp sql.NullTime

	err := database.QueryRow(`SELECT kind, sample_id, status, journey_id, worker_id, sequence,
		from_location_id, to_location_id, node_id, laboratory_id, offer_expires_at
		FROM assignments WHERE assignment_id=$1`, assignmentID).Scan(
		&kind, &sampleID, &status, &jid, &workerID, &seq, &fromLoc, &toLoc, &nodeID, &labID, &offerExp)

	if err != nil {
		return nil
	}

	wi.SampleID = sampleID
	wi.Status = status
	wi.Sequence = seq
	if jid.Valid {
		wi.JourneyID = &jid.String
	}
	if fromLoc.Valid {
		wi.FromLocationID = &fromLoc.String
	}
	if toLoc.Valid {
		wi.ToLocationID = &toLoc.String
	}
	if nodeID.Valid {
		wi.NodeID = &nodeID.String
	}
	if labID.Valid {
		wi.LaboratoryID = &labID.String
	}
	if offerExp.Valid {
		wi.OfferExpiresAt = &offerExp.Time
	}

	timeline, _ := h.svc.GetTimeline(database, assignmentID)
	wi.History = timeline

	return &wi
}

// ── Assignments ──

func (h *Handler) AcceptAssignment(w http.ResponseWriter, r *http.Request) {
	claims := middleware.GetClaims(r)
	assignmentID := r.PathValue("assignmentId")

	// Verify this assignment belongs to this worker
	var workerID string
	var status string
	err := h.DB.QueryRow(`SELECT worker_id, status FROM assignments WHERE assignment_id=$1`, assignmentID).Scan(&workerID, &status)
	if err != nil {
		h.err(w, 404, "assignment not found", "NOT_FOUND")
		return
	}
	if workerID != claims.UserID {
		h.err(w, 403, "assignment not offered to you", "FORBIDDEN")
		return
	}
	if status != "offered" {
		h.err(w, 409, "assignment already responded to", "CONFLICT")
		return
	}

	h.DB.Exec(`UPDATE assignments SET status='accepted', updated_at=NOW() WHERE assignment_id=$1`, assignmentID)
	h.svc.WriteAudit(h.DB, claims.UserID, middleware.GetSelectedRole(r), "accept_assignment", "assignment", assignmentID, true, nil)

	var aid, kind, sampleID string
	h.DB.QueryRow(`SELECT assignment_id, kind, sample_id FROM assignments WHERE assignment_id=$1`, assignmentID).Scan(&aid, &kind, &sampleID)
	wi := h.assignmentToWorkItem(h.DB, assignmentID, claims)
	h.respond(w, 200, wi)
}

func (h *Handler) DeclineAssignment(w http.ResponseWriter, r *http.Request) {
	claims := middleware.GetClaims(r)
	assignmentID := r.PathValue("assignmentId")

	var workerID string
	var status string
	err := h.DB.QueryRow(`SELECT worker_id, status FROM assignments WHERE assignment_id=$1`, assignmentID).Scan(&workerID, &status)
	if err != nil {
		h.err(w, 404, "assignment not found", "NOT_FOUND")
		return
	}
	if workerID != claims.UserID {
		h.err(w, 403, "assignment not offered to you", "FORBIDDEN")
		return
	}
	if status != "offered" {
		h.err(w, 409, "assignment already responded to", "CONFLICT")
		return
	}

	h.DB.Exec(`UPDATE assignments SET status='declined', declined_at=NOW(), updated_at=NOW() WHERE assignment_id=$1`, assignmentID)
	h.DB.Exec(`UPDATE users SET decline_count=decline_count+1 WHERE user_id=$1`, claims.UserID)
	h.svc.WriteAudit(h.DB, claims.UserID, middleware.GetSelectedRole(r), "decline_assignment", "assignment", assignmentID, true, nil)

	wi := h.assignmentToWorkItem(h.DB, assignmentID, claims)
	h.respond(w, 200, wi)
}

