func (h *Handler) ConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	claims := middleware.GetClaims(r)
	body, err := h.readBody(r)
	if err != nil {
		h.err(w, 400, "invalid request body", "BAD_REQUEST")
		return
	}
	handoffID, _ := body["handoffId"].(string)
	side, _ := body["side"].(string) // "sender" or "receiver"

	var fromWorker, toWorker, status string
	var senderConfirmed, receiverConfirmed bool
	var sampleID string
	err = h.DB.QueryRow(`SELECT sample_id, from_worker_id, to_worker_id, status, sender_confirmed, receiver_confirmed
		FROM handoffs WHERE handoff_id=$1`, handoffID).Scan(&sampleID, &fromWorker, &toWorker, &status, &senderConfirmed, &receiverConfirmed)
	if err != nil {
		h.err(w, 404, "handoff not found", "NOT_FOUND")
		return
	}

	if status == "completed" {
		h.err(w, 409, "handoff already completed", "CONFLICT")
		return
	}

	switch side {
	case "sender":
		if claims.UserID != fromWorker {
			h.err(w, 403, "not the sender", "FORBIDDEN")
			return
		}
		h.DB.Exec(`UPDATE handoffs SET sender_confirmed=TRUE, sender_confirmed_at=NOW(), status=CASE WHEN receiver_confirmed THEN 'completed' ELSE 'sender_confirmed' END, completed_at=CASE WHEN receiver_confirmed THEN NOW() ELSE NULL END WHERE handoff_id=$1`, handoffID)
		if receiverConfirmed {
			h.DB.Exec(`UPDATE samples SET current_holder_id=$1, pending_handoff_id=NULL, status='in_transit', updated_at=NOW() WHERE sample_id=$2`, toWorker, sampleID)
		}
	case "receiver":
		if claims.UserID != toWorker {
			h.err(w, 403, "not the receiver", "FORBIDDEN")
			return
		}
		h.DB.Exec(`UPDATE handoffs SET receiver_confirmed=TRUE, receiver_confirmed_at=NOW(), status=CASE WHEN sender_confirmed THEN 'completed' ELSE 'receiver_confirmed' END, completed_at=CASE WHEN sender_confirmed THEN NOW() ELSE NULL END WHERE handoff_id=$1`, handoffID)
		if senderConfirmed {
			h.DB.Exec(`UPDATE samples SET current_holder_id=$1, pending_handoff_id=NULL, status='in_transit', updated_at=NOW() WHERE sample_id=$2`, toWorker, sampleID)
		}
	default:
		h.err(w, 400, "side must be 'sender' or 'receiver'", "BAD_REQUEST")
		return
	}

	h.svc.WriteAudit(h.DB, claims.UserID, middleware.GetSelectedRole(r), "confirm_handoff", "handoff", handoffID, true, map[string]interface{}{"side": side})
	h.respond(w, 200, map[string]string{"handoffId": handoffID, "status": "confirmed"})
}

