}

func New(svc *service.Service, db *sql.DB) *Handler {
	return &Handler{svc: svc, DB: db}
}

func (h *Handler) respond(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if data != nil {
		json.NewEncoder(w).Encode(model.APIResponse{Data: data})
	}
}

func (h *Handler) err(w http.ResponseWriter, status int, msg, code string) {
