		h.err(w, 401, "unauthorized", "UNAUTHORIZED")
		return
	}
	h.DB.Exec(`INSERT INTO jwti_blacklist (jti, expires_at) VALUES ($1, $2) ON CONFLICT DO NOTHING`,
		claims.ID, claims.ExpiresAt.Time)
	h.audit(r, "logout", "user", claims.UserID, true, nil)
