	body, err := h.readBody(r)
	if err != nil {
		h.err(w, 400, "invalid request body", "BAD_REQUEST")
		return
	}
	claims := middleware.GetClaims(r)
	result, err := h.svc.ConfirmHandoff(h.DB, claims.UserID, body, h.actorRole(r))
	if err != nil {
		code := 500
		msg := err.Error()
		if msg == "not the sender" || msg == "not the receiver" {
			code = 403
		}
		if msg == "handoff not found" {
			code = 404
		}
		if msg == "handoff already completed" {
			code = 409
		}
		h.err(w, code, msg, "ERROR")
		return
	}
	h.audit(r, "confirm_handoff", "handoff", fmt.Sprintf("%v", body["handoffId"]), true, body)
	h.respond(w, 200, result)
}

