// ── Helpers ──

func uid() string {
	return fmt.Sprintf("%08x", time.Now().UnixNano()%0xFFFFFFFF)
}

func getStatusForErr(err error) int {
	if err == nil {
		return 200
	}
	msg := err.Error()
	switch msg {
	case "assignment not found", "handoff not found":
		return 404
	case "assignment not offered to you", "not the sender", "not the receiver":
		return 403
	case "assignment already responded to", "handoff already completed":
		return 409
	default:
		return 500
	}
}

func getCodeForErr(err error) string {
	if err == nil {
		return "OK"
	}
	msg := err.Error()
	switch msg {
	case "assignment not found", "handoff not found":
		return "NOT_FOUND"
	case "assignment not offered to you", "not the sender", "not the receiver":
		return "FORBIDDEN"
	case "assignment already responded to", "handoff already completed":
		return "CONFLICT"
	default:
		return "INTERNAL"
	}
}

