func (s *Service) GetWorkerLocations(db_ *sql.DB) ([]map[string]interface{}, error) {
	rows, err := db_.Query(`SELECT user_id, username, full_name, latitude, longitude, location_recorded_at,
		ARRAY(SELECT role FROM user_roles WHERE user_id = users.user_id) as roles
		FROM users WHERE latitude != 0 AND longitude != 0 AND active = TRUE`)
