func (s *Service) GetCollectionPlans(db_ *sql.DB, workerID string) ([]interface{}, error) {
	rows, err := db_.Query(`SELECT a.assignment_id, a.sample_id, a.status, a.sequence,
		s.sample_type_id, s.origin_lat, s.origin_lng, s.delivery_deadline,
		s.earliest_collection_at, s.latest_collection_at
		FROM assignments a JOIN samples s ON a.sample_id = s.sample_id
		WHERE a.worker_id = $1 AND a.kind = 'collection' ORDER BY a.sequence`, workerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var plans []interface{}
	for rows.Next() {
		var aid, sid, status, stID string
		var seq int
		var lat, lng float64
		var deadline time.Time
		var earliest, latest sql.NullTime
		rows.Scan(&aid, &sid, &status, &seq, &stID, &lat, &lng, &deadline, &earliest, &latest)
		plan := map[string]interface{}{
			"assignmentId":     aid,
			"sampleId":         sid,
			"status":           status,
			"sequence":         seq,
			"sampleTypeId":     stID,
			"origin":           map[string]float64{"latitude": lat, "longitude": lng},
			"deliveryDeadline": deadline,
		}
		if earliest.Valid {
			plan["earliestCollectionAt"] = earliest.Time
		}
		if latest.Valid {
			plan["latestCollectionAt"] = latest.Time
		}
		plans = append(plans, plan)
	}
	return plans, nil
}

