func (s *Service) CreateLocation(db_ *sql.DB, req map[string]interface{}) (*model.Location, error) {
	locID, _ := req["locationId"].(string)
	if locID == "" {
		locID = uid()
	}
	name, _ := req["name"].(string)
	lat, lng := 0.0, 0.0
	if coord, ok := req["coordinate"].(map[string]interface{}); ok {
		if v, ok := coord["latitude"].(float64); ok {
			lat = v
		}
		if v, ok := coord["longitude"].(float64); ok {
			lng = v
		}
	}

	_, err := db_.Exec(`INSERT INTO locations (location_id, name, latitude, longitude, coverage_km, handling_minutes)
		VALUES ($1, $2, $3, $4, 5, 10) ON CONFLICT (location_id) DO UPDATE SET name=$2, latitude=$3, longitude=$4`,
		locID, name, lat, lng)
	if err != nil {
		return nil, err
	}

	if funcs, ok := req["functions"].(map[string]interface{}); ok {
		sets := []string{}
		args := []interface{}{locID}
		i := 2
		for _, key := range []string{"collection_point", "transfer_point", "hub", "laboratory"} {
			if v, ok := funcs[key].(bool); ok && v {
				sets = append(sets, fmt.Sprintf("fn_%s=TRUE", key))
				args = append(args, nil)
				i++
			}
		}
		if len(sets) > 0 {
			db_.Exec(fmt.Sprintf("UPDATE locations SET %s WHERE location_id=$1", strings.Join(sets, ",")), args...)
		}
	}

	if capacity, ok := req["capacity"].(map[string]interface{}); ok {
		s.ConfigureCapacity(db_, "location", locID, capacity)
	}

	if sampleTypes, ok := req["acceptedSampleTypeIds"].([]interface{}); ok {
		for _, st := range sampleTypes {
			if sts, ok := st.(string); ok {
				db_.Exec(`INSERT INTO laboratory_sample_types (location_id, sample_type_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, locID, sts)
			}
		}
	}

	return s.GetLocation(db_, locID)
}

