func (h *Handler) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	body, err := h.decode(r)
	if err != nil {
		h.fail(w, 400, "invalid body", "BAD_REQUEST")
		return
	}
	username, _ := body["username"].(string)
	password, _ := body["password"].(string)
	if username == "" || password == "" {
		h.fail(w, 400, "username and password required", "BAD_REQUEST")
		return
	}
	resp, apiErr := h.svc.Authenticate(h.DB, username, password)
	if apiErr != nil {
		if apiErr.Code == "FORBIDDEN" {
			h.fail(w, 403, apiErr.Error, apiErr.Code)
		} else {
			h.fail(w, 401, apiErr.Error, apiErr.Code)
		}
		return
	}
	h.audit(r, "login", "user", resp.UserID, true, nil)
	h.ok(w, 200, resp)
}

func (h *Handler) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
	body, err := h.decode(r)
	if err != nil {
		h.fail(w, 400, "invalid body", "BAD_REQUEST")
		return
	}
	role, _ := body["role"].(string)
	if role == "" {
		h.fail(w, 400, "role required", "BAD_REQUEST")
		return
	}
	c := middleware.GetClaims(r)
	if c == nil {
		h.fail(w, 401, "unauthorized", "UNAUTHORIZED")
		return
	}
	valid := false
	for _, rl := range c.Roles {
		if rl == role {
			valid = true
			break
		}
	}
	if !valid {
		h.fail(w, 403, "role not assigned", "FORBIDDEN")
		return
	}
	token, _ := middleware.SwitchRole(r, h.DB, role)
	h.ok(w, 200, map[string]interface{}{"token": token, "role": role})
}

