func serviceabilityReqFromBody(body map[string]interface{}) model.ServiceabilityCheckRequest {
var req model.ServiceabilityCheckRequest
if origin, ok := body["origin"].(map[string]interface{}); ok {
req.Origin.Latitude, _ = origin["latitude"].(float64)
req.Origin.Longitude, _ = origin["longitude"].(float64)
}
req.OriginType, _ = body["originType"].(string)
req.OriginNodeID, _ = body["originNodeId"].(string)
req.SampleTypeID, _ = body["sampleTypeId"].(string)
if t, ok := body["requestedAt"].(string); ok {
req.RequestedAt, _ = time.Parse(time.RFC3339, t)
}
if t, ok := body["deliveryDeadline"].(string); ok {
req.DeliveryDeadline, _ = time.Parse(time.RFC3339, t)
}
if t, ok := body["earliestCollectionAt"].(string); ok {
req.EarliestCollectionAt, _ = time.Parse(time.RFC3339, t)
}
if t, ok := body["latestCollectionAt"].(string); ok {
req.LatestCollectionAt, _ = time.Parse(time.RFC3339, t)
}
return req
}

