func (h *Handler) ConfirmHandoff(w http.ResponseWriter, r *http.Request) {
body, err := h.decode(r)
if err != nil {
h.fail(w, 400, "invalid body", "BAD_REQUEST")
return
}
result, err := h.svc.ConfirmHandoff(h.DB, h.uid(r), body)
if err != nil {
code := 500
msg := err.Error()
switch msg {
case "not the sender", "not the receiver":
code = 403
case "handoff not found":
code = 404
case "handoff already completed":
code = 409
}
h.fail(w, code, msg, "ERROR")
return
}
hid, _ := body["handoffId"].(string)
h.audit(r, "confirm_handoff", "handoff", hid, true, body)
h.ok(w, 201, result)
}

