		}
	}
	return &st, err
}

// ── Serviceability ──

func (s *Service) CheckServiceability(db_ *sql.DB, req model.ServiceabilityCheckRequest) *model.ServiceabilityResponse {
	// Find nearest active collection node within coverage
	originType := model.OriginNode
	if req.OriginType != nil {
		originType = *req.OriginType
	}

	// For home/clinic origins, find nearest active collection point
	rows, err := db_.Query(`SELECT location_id, name, latitude, longitude, coverage_km FROM locations
		WHERE active = TRUE AND fn_collection_point = TRUE`)
	if err != nil {
		return &model.ServiceabilityResponse{Serviceable: false, Reason: "internal error"}
	}
	defer rows.Close()

	var nearest *model.ServiceabilityRegion
	minDist := math.MaxFloat64
	for rows.Next() {
		var r model.ServiceabilityRegion
		rows.Scan(&r.LocationID, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm)
		dist := haversine(req.Origin.Latitude, req.Origin.Longitude, r.Latitude, r.Longitude)
		if dist < minDist {
			minDist = dist
			nearest = &r
		}
	}

	if originType != model.OriginNode && nearest != nil && minDist > nearest.CoverageKm {
		return &model.ServiceabilityResponse{Serviceable: false, Reason: "origin outside coverage area"}
	}

	// Check there's an active laboratory that accepts this sample type
	var labCount int
	db_.QueryRow(`SELECT COUNT(*) FROM locations l
		JOIN laboratory_sample_types lst ON l.location_id = lst.location_id
		WHERE l.active = TRUE AND l.fn_laboratory = TRUE AND lst.sample_type_id = $1`, req.SampleTypeID).Scan(&labCount)
	if labCount == 0 {
		return &model.ServiceabilityResponse{Serviceable: false, Reason: "no accepting laboratory"}
	}

	// Check valid route exists
	hasRoute := s.hasValidRoute(db_, req)
	if !hasRoute {
		return &model.ServiceabilityResponse{Serviceable: false, Reason: "no valid route"}
	}

	// Check capacity
	if !s.hasCapacity(db_, req) {
		return &model.ServiceabilityResponse{Serviceable: false, Reason: "insufficient capacity"}
	}

	// Check deadline can be met
	if !s.canMeetDeadline(db_, req) {
		return &model.ServiceabilityResponse{Serviceable: false, Reason: "cannot meet deadline"}
	}

	return &model.ServiceabilityResponse{Serviceable: true}
}

func (s *Service) hasValidRoute(db_ *sql.DB, req model.ServiceabilityCheckRequest) bool {
	// A simple BFS to check if there's a path from any collection point to an accepting lab
	// through active connections
	rows, err := db_.Query(`SELECT DISTINCT l.location_id FROM locations l
		WHERE l.active = TRUE AND l.fn_collection_point = TRUE`)
	if err != nil {
		return false
	}
	defer rows.Close()

	targetLabs := s.getAcceptingLabs(db_, req.SampleTypeID)
	if len(targetLabs) == 0 {
		return false
	}

	for rows.Next() {
		var cpID string
		rows.Scan(&cpID)
		for _, labID := range targetLabs {
			if s.hasPath(db_, cpID, labID) {
				return true
			}
		}
	}
	return false
}

func (s *Service) getAcceptingLabs(db_ *sql.DB, stID string) []string {
	rows, err := db_.Query(`SELECT l.location_id FROM locations l
		JOIN laboratory_sample_types lst ON l.location_id = lst.location_id
		WHERE l.active = TRUE AND l.fn_laboratory = TRUE AND lst.sample_type_id = $1`, stID)
	if err != nil {
		return nil
	}
	defer rows.Close()
	var ids []string
	for rows.Next() {
		var id string
		rows.Scan(&id)
		ids = append(ids, id)
	}
	return ids
}

func (s *Service) hasPath(db_ *sql.DB, from, to string) bool {
	visited := map[string]bool{}
	queue := []string{from}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		if current == to {
			return true
		}
		if visited[current] {
			continue
		}
		visited[current] = true
		rows, err := db_.Query(`SELECT to_location_id FROM connections WHERE from_location_id=$1 AND active=TRUE`, current)
		if err != nil {
			continue
		}
		defer rows.Close()
		for rows.Next() {
			var next string
			rows.Scan(&next)
			queue = append(queue, next)
		}
	}
	return false
}

func (s *Service) hasCapacity(db_ *sql.DB, req model.ServiceabilityCheckRequest) bool {
	st, err := s.GetSampleType(db_, req.SampleTypeID)
	if err != nil {
		return false
	}
	entityType := "location"
	if st.RequiresCooledRoute {
		// Check for at least one location with cooled capacity
		var count int
		db_.QueryRow(`SELECT COUNT(*) FROM capacity WHERE entity_type=$1 AND cooled_capacity_units > cooled_reserved_units`, entityType).Scan(&count)
		return count > 0
	}
	var count int
	db_.QueryRow(`SELECT COUNT(*) FROM capacity WHERE entity_type=$1 AND capacity_units > reserved_units`, entityType).Scan(&count)
	return count > 0
}

func (s *Service) canMeetDeadline(db_ *sql.DB, req model.ServiceabilityCheckRequest) bool {
	// Simple: just check if there's enough time
	return time.Now().Before(req.DeliveryDeadline)
}

func haversine(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180
	dLng := (lng2 - lng1) * math.Pi / 180
	a := math.Sin(dLat/2)*math.Sin(dLat/2) + math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*math.Sin(dLng/2)*math.Sin(dLng/2)
	return R * 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
}

// ── Serviceability recalculation ──

func (s *Service) RecalculateServiceability(db_ *sql.DB) (*model.ServiceabilitySnapshot, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	var maxVersion int
	db_.QueryRow(`SELECT COALESCE(MAX(version), 0) FROM serviceability_snapshots`).Scan(&maxVersion)
	newVersion := maxVersion + 1

	rows, err := db_.Query(`SELECT location_id, name, latitude, longitude, coverage_km FROM locations WHERE active=TRUE AND fn_collection_point=TRUE`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var regions []model.ServiceabilityRegion
	for rows.Next() {
		var r model.ServiceabilityRegion
		rows.Scan(&r.LocationID, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm)
		regions = append(regions, r)
	}

	snap := model.ServiceabilitySnapshot{
		Version:   newVersion,
		Regions:   regions,
		UpdatedAt: time.Now(),
	}

	data, _ := json.Marshal(snap)
	db_.Exec(`INSERT INTO serviceability_snapshots (version, data, updated_at) VALUES ($1, $2, NOW()) ON CONFLICT (version) DO UPDATE SET data=$2, updated_at=NOW()`, newVersion, data)

	return &snap, nil
}

func (s *Service) GetServiceability(db_ *sql.DB) (*model.ServiceabilitySnapshot, error) {
	var version int
	var data []byte
	err := db_.QueryRow(`SELECT version, data FROM serviceability_snapshots ORDER BY version DESC LIMIT 1`).Scan(&version, &data)
	if err != nil {
		return &model.ServiceabilitySnapshot{Version: 0, Regions: nil, UpdatedAt: time.Now()}, nil
	}
	var snap model.ServiceabilitySnapshot
	json.Unmarshal(data, &snap)
	return &snap, nil
}

