func (s *Service) ListUsers(database *sql.DB) ([]model.User, error) {
	rows, err := database.Query(`SELECT user_id FROM users ORDER BY username`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var users []model.User
	for rows.Next() {
		var id string
		rows.Scan(&id)
		u, err := s.GetUser(database, id)
		if err == nil {
			users = append(users, *u)
		}
	}
	if users == nil {
		users = []model.User{}
	}
	return users, nil
}

func (s *Service) UpdateUser(database *sql.DB, userID string, body map[string]interface{}) error {
	if locID, ok := body["assignedLocationId"].(string); ok {
		database.Exec(`UPDATE users SET assigned_location_id=$1 WHERE user_id=$2`, locID, userID)
	}
	if active, ok := body["active"].(bool); ok {
		database.Exec(`UPDATE users SET active=$1 WHERE user_id=$2`, active, userID)
	}
	if fullName, ok := body["fullName"].(string); ok {
		database.Exec(`UPDATE users SET full_name=$1 WHERE user_id=$2`, fullName, userID)
	}
	if roles, ok := body["roles"].([]interface{}); ok {
		database.Exec(`DELETE FROM user_roles WHERE user_id=$1`, userID)
		for _, r := range roles {
			if rs, ok := r.(string); ok {
				database.Exec(`INSERT INTO user_roles (user_id, role) VALUES ($1, $2) ON CONFLICT DO NOTHING`, userID, rs)
			}
		}
	}
	if certs, ok := body["certifications"].([]interface{}); ok {
		database.Exec(`DELETE FROM user_certifications WHERE user_id=$1`, userID)
		for _, c := range certs {
			if cm, ok := c.(map[string]interface{}); ok {
				code, _ := cm["code"].(string)
				active, _ := cm["active"].(bool)
				if code != "" {
					database.Exec(`INSERT INTO user_certifications (user_id, code, active) VALUES ($1, $2, $3) ON CONFLICT (user_id, code) DO UPDATE SET active=$3`, userID, code, active)
				}
			}
		}
	}
	return nil
}

func (s *Service) UpdateLocation(database *sql.DB, locID string, body map[string]interface{}) error {
	if name, ok := body["name"].(string); ok {
		database.Exec(`UPDATE locations SET name=$1 WHERE location_id=$2`, name, locID)
	}
	if active, ok := body["active"].(bool); ok {
		database.Exec(`UPDATE locations SET active=$1 WHERE location_id=$2`, active, locID)
	}
	if coord, ok := body["coordinate"].(map[string]interface{}); ok {
		if lat, ok := coord["latitude"].(float64); ok {
			if lng, ok := coord["longitude"].(float64); ok {
				database.Exec(`UPDATE locations SET latitude=$1, longitude=$2 WHERE location_id=$3`, lat, lng, locID)
			}
		}
	}
	if funcs, ok := body["functions"].(map[string]interface{}); ok {
		for _, key := range []string{"collection_point", "transfer_point", "hub", "laboratory"} {
			if v, ok := funcs[key].(bool); ok {
				database.Exec(fmt.Sprintf(`UPDATE locations SET fn_%s=$1 WHERE location_id=$2`, key), v, locID)
			}
		}
	}
	if capacity, ok := body["capacity"].(map[string]interface{}); ok {
		s.ConfigureCapacity(database, "location", locID, capacity)
	}
	if stIDs, ok := body["acceptedSampleTypeIds"].([]interface{}); ok {
		database.Exec(`DELETE FROM laboratory_sample_types WHERE location_id=$1`, locID)
		for _, st := range stIDs {
			if sts, ok := st.(string); ok {
				database.Exec(`INSERT INTO laboratory_sample_types (location_id, sample_type_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, locID, sts)
			}
		}
	}
	return nil
}

func (s *Service) UpdateConnection(database *sql.DB, connID string, body map[string]interface{}) error {
	if active, ok := body["active"].(bool); ok {
		database.Exec(`UPDATE connections SET active=$1 WHERE connection_id=$2`, active, connID)
	}
	if capacity, ok := body["capacity"].(map[string]interface{}); ok {
		s.ConfigureCapacity(database, "connection", connID, capacity)
	}
	return nil
}

func (s *Service) GetSampleTypes(database *sql.DB) ([]model.SampleType, error) {
	rows, err := database.Query(`SELECT sample_type_id FROM sample_types`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var types []model.SampleType
	for rows.Next() {
		var id string
		rows.Scan(&id)
		st, err := s.GetSampleType(database, id)
		if err == nil {
			types = append(types, *st)
		}
	}
	if types == nil {
		types = []model.SampleType{}
	}
	return types, nil
}

func (s *Service) CreateSampleRequest(database *sql.DB, requesterID string, body map[string]interface{}) (*model.Sample, error) {
	sampleID := uid()
	originLat, originLng := 0.0, 0.0
	if coord, ok := body["origin"].(map[string]interface{}); ok {
		originLat, _ = coord["latitude"].(float64)
		originLng, _ = coord["longitude"].(float64)
	}
	stID, _ := body["sampleTypeId"].(string)
	originType, _ := body["originType"].(string)
	originNodeID, _ := body["originNodeId"].(string)
	deadlineStr, _ := body["deliveryDeadline"].(string)
	earliestStr, _ := body["earliestCollectionAt"].(string)
	latestStr, _ := body["latestCollectionAt"].(string)

	if originType == "" {
		originType = "node"
	}

	deadline, _ := time.Parse(time.RFC3339, deadlineStr)
	if deadline.IsZero() {
		deadline = time.Now().Add(24 * time.Hour)
	}

	var earliest, latest sql.NullTime
	if t, err := time.Parse(time.RFC3339, earliestStr); err == nil {
		earliest = sql.NullTime{Time: t, Valid: true}
	}
	if t, err := time.Parse(time.RFC3339, latestStr); err == nil {
		latest = sql.NullTime{Time: t, Valid: true}
	}

	st, err := s.GetSampleType(database, stID)
	if err != nil {
		return nil, fmt.Errorf("invalid sample type: %s", stID)
	}

	requestID := uid()

	_, err = database.Exec(`INSERT INTO samples (sample_id, request_id, requester_id, origin_lat, origin_lng,
		origin_type, origin_node_id, requested_at, delivery_deadline,
		earliest_collection_at, latest_collection_at, sample_type_id,
		container_type, temperature_min_c, temperature_max_c, status, sealed,
		serviceability, latitude, longitude)
		VALUES ($1, $2, $3, $4, $5, $6, $7, NOW(), $8, $9, $10, $11, $12, $13, $14, 'requested', FALSE, 'unchecked', $4, $5)`,
		sampleID, requestID, requesterID, originLat, originLng,
		ns(originType), ns(originNodeID), deadline, earliest, latest,
		stID, st.ContainerType, st.TemperatureMinC, st.TemperatureMaxC)

	if err != nil {
		return nil, err
	}

	for _, inc := range st.IncompatibleSampleTypes {
		database.Exec(`INSERT INTO sample_incompatibilities (sample_id, incompatible_type_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, sampleID, inc)
	}

	return &model.Sample{
		SampleID:     sampleID,
		RequestID:    requestID,
		RequesterID:  requesterID,
		Status:       "requested",
		SampleTypeID: stID,
	}, nil
}

func ns(s string) sql.NullString {
	if s == "" {
		return sql.NullString{}
	}
	return sql.NullString{String: s, Valid: true}
}

func (s *Service) GetSampleLifecycle(database *sql.DB, sampleID string) (map[string]interface{}, error) {
	var originLat, originLng sql.NullFloat64
	var originNodeID, curHolderID, journeyID, labID, recLabID, handoffID sql.NullString
	var reqID, requesterID, status, stID, originType, serv string
	var reqAt, deadline, earliest, latest, locRec sql.NullTime
	var exceptionReason, exceptionRecordedBy sql.NullString
	var exceptionObserved sql.NullTime
	var sealed bool
	var lat, lng sql.NullFloat64

	err := database.QueryRow(`SELECT sample_id, request_id, requester_id, origin_lat, origin_lng,
		origin_type, origin_node_id, requested_at, delivery_deadline,
		earliest_collection_at, latest_collection_at, sample_type_id,
		status, sealed, serviceability, current_holder_id, active_journey_id,
		target_laboratory_id, received_laboratory_id, pending_handoff_id,
		exception_reason, exception_observed_at, exception_recorded_by,
		latitude, longitude, location_recorded_at
		FROM samples WHERE sample_id=$1`, sampleID).Scan(
		&sampleID, &reqID, &requesterID, &originLat, &originLng,
		&originType, &originNodeID, &reqAt, &deadline,
		&earliest, &latest, &stID,
		&status, &sealed, &serv, &curHolderID, &journeyID,
		&labID, &recLabID, &handoffID,
		&exceptionReason, &exceptionObserved, &exceptionRecordedBy,
		&lat, &lng, &locRec)
	if err != nil {
		return nil, err
	}

	sm := map[string]interface{}{
		"sampleId":       sampleID,
		"requestId":      reqID,
		"requesterId":    requesterID,
		"originType":     originType,
		"sampleTypeId":   stID,
		"status":         status,
		"sealed":         sealed,
		"serviceability": serv,
	}

	if originLat.Valid {
		sm["origin"] = map[string]float64{"latitude": originLat.Float64, "longitude": originLng.Float64}
	}
	if originNodeID.Valid {
		sm["originNodeId"] = originNodeID.String
	}
	if reqAt.Valid {
		sm["requestedAt"] = reqAt.Time
	}
	if deadline.Valid {
		sm["deliveryDeadline"] = deadline.Time
	}
	if earliest.Valid {
		sm["earliestCollectionAt"] = earliest.Time
	}
	if latest.Valid {
		sm["latestCollectionAt"] = latest.Time
	}
	if curHolderID.Valid {
		sm["currentHolderId"] = curHolderID.String
	}
	if journeyID.Valid {
		sm["activeJourneyId"] = journeyID.String
	}
	if labID.Valid {
		sm["targetLaboratoryId"] = labID.String
	}
	if recLabID.Valid {
		sm["receivedLaboratoryId"] = recLabID.String
	}
	if handoffID.Valid {
		sm["pendingHandoffId"] = handoffID.String
	}
	if exceptionReason.Valid {
		sm["exception"] = map[string]interface{}{
			"reason":     exceptionReason.String,
			"observedAt": exceptionObserved.Time,
			"recordedBy": exceptionRecordedBy.String,
		}
	}
	if lat.Valid {
		sm["latestLocation"] = map[string]float64{"latitude": lat.Float64, "longitude": lng.Float64}
	}
	if locRec.Valid {
		sm["locationRecordedAt"] = locRec.Time
		sm["locationStale"] = time.Since(locRec.Time) > 15*time.Minute
	} else {
		sm["locationStale"] = false
	}

	timeline, _ := s.GetTimeline(database, sampleID)
	sm["timeline"] = timeline

	return sm, nil
}

func (s *Service) GetRequesterSamples(database *sql.DB, requesterID string) ([]interface{}, error) {
	rows, err := database.Query(`SELECT sample_id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, requesterID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var samples []interface{}
	for rows.Next() {
		var id string
		rows.Scan(&id)
		sm, err := s.GetSampleLifecycle(database, id)
		if err == nil {
			samples = append(samples, sm)
		}
	}
	if samples == nil {
		samples = []interface{}{}
	}
	return samples, nil
}

func (s *Service) GetRoleWork(database *sql.DB, userID, role string, allRoles []string) (*model.RoleWork, error) {
	work := &model.RoleWork{
		Pending:    []model.RoleWorkItem{},
		InProgress: []model.RoleWorkItem{},
		Completed:  []model.RoleWorkItem{},
	}

	switch role {
	case "requester":
		rows, _ := database.Query(`SELECT sample_id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, userID)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var id string
				rows.Scan(&id)
				sm, err := s.GetSampleLifecycle(database, id)
				if err == nil {
					work.Pending = append(work.Pending, sm)
				}
			}
		}
	case "collection_professional", "delivery_partner", "node_handler", "laboratory_team":
		kind := map[string]string{
			"collection_professional": "collection",
			"delivery_partner":        "transport",
			"node_handler":            "node",
			"laboratory_team":         "laboratory",
		}[role]
		aRows, _ := database.Query(`SELECT assignment_id, status FROM assignments WHERE worker_id=$1 AND kind=$2 ORDER BY created_at DESC`, userID, kind)
		if aRows != nil {
			defer aRows.Close()
			for aRows.Next() {
				var aid, status string
				aRows.Scan(&aid, &status)
				item := s.getAssignmentInfo(database, aid)
				if item != nil {
					if status == "completed" || status == "declined" || status == "cancelled" {
						work.Completed = append(work.Completed, item)
					} else if status == "in_progress" || status == "accepted" {
						work.InProgress = append(work.InProgress, item)
					} else {
						work.Pending = append(work.Pending, item)
					}
				}
			}
		}
	case "dispatcher", "administrator":
		sRows, _ := database.Query(`SELECT sample_id FROM samples ORDER BY created_at DESC LIMIT 50`)
		if sRows != nil {
			defer sRows.Close()
			for sRows.Next() {
				var id string
				sRows.Scan(&id)
				sm, err := s.GetSampleLifecycle(database, id)
				if err == nil {
					work.Pending = append(work.Pending, sm)
				}
			}
		}
	}

	return work, nil
}

func (s *Service) getAssignmentInfo(database *sql.DB, assignmentID string) map[string]interface{} {
	var kind, sampleID, status string
	var seq int
	var jid, workerID, fromLoc, toLoc, nodeID, labID sql.NullString
	var offerExp sql.NullTime

	err := database.QueryRow(`SELECT kind, sample_id, status, journey_id, worker_id, sequence,
		from_location_id, to_location_id, node_id, laboratory_id, offer_expires_at
		FROM assignments WHERE assignment_id=$1`, assignmentID).Scan(
		&kind, &sampleID, &status, &jid, &workerID, &seq, &fromLoc, &toLoc, &nodeID, &labID, &offerExp)
	if err != nil {
		return nil
	}

	info := map[string]interface{}{
		"assignmentId": assignmentID,
		"kind":         kind,
		"sampleId":     sampleID,
		"status":       status,
		"sequence":     seq,
	}
	if jid.Valid {
		info["journeyId"] = jid.String
	}
	if fromLoc.Valid {
		info["fromLocationId"] = fromLoc.String
	}
	if toLoc.Valid {
		info["toLocationId"] = toLoc.String
	}
	if nodeID.Valid {
		info["nodeId"] = nodeID.String
	}
	if labID.Valid {
		info["laboratoryId"] = labID.String
	}
	if offerExp.Valid {
		info["offerExpiresAt"] = offerExp.Time
	}

	timeline, _ := s.GetTimeline(database, assignmentID)
	info["timeline"] = timeline

	return info
}

func (s *Service) AcceptAssignment(database *sql.DB, workerID, assignmentID, role string) (map[string]interface{}, error) {
	var assnWorker, status string
	err := database.QueryRow(`SELECT worker_id, status FROM assignments WHERE assignment_id=$1`, assignmentID).Scan(&assnWorker, &status)
	if err != nil {
		return nil, fmt.Errorf("assignment not found")
	}
	if assnWorker != workerID {
		return nil, fmt.Errorf("assignment not offered to you")
	}
	if status != "offered" {
		return nil, fmt.Errorf("assignment already responded to")
	}
	database.Exec(`UPDATE assignments SET status='accepted', updated_at=NOW() WHERE assignment_id=$1`, assignmentID)
	database.Exec(`UPDATE users SET decline_count=GREATEST(decline_count-1, 0) WHERE user_id=$1`, workerID)
	return s.getAssignmentInfo(database, assignmentID), nil
}

func (s *Service) DeclineAssignment(database *sql.DB, workerID, assignmentID, role string) (map[string]interface{}, error) {
	var assnWorker, status string
	err := database.QueryRow(`SELECT worker_id, status FROM assignments WHERE assignment_id=$1`, assignmentID).Scan(&assnWorker, &status)
	if err != nil {
		return nil, fmt.Errorf("assignment not found")
	}
	if assnWorker != workerID {
		return nil, fmt.Errorf("assignment not offered to you")
	}
	if status != "offered" {
		return nil, fmt.Errorf("assignment already responded to")
	}
	database.Exec(`UPDATE assignments SET status='declined', declined_at=NOW(), updated_at=NOW() WHERE assignment_id=$1`, assignmentID)
	database.Exec(`UPDATE users SET decline_count=decline_count+1 WHERE user_id=$1`, workerID)
	return s.getAssignmentInfo(database, assignmentID), nil
}

func (s *Service) CollectAndSealSample(database *sql.DB, workerID string, body map[string]interface{}, role string) (map[string]interface{}, error) {
	sampleID, _ := body["sampleId"].(string)
	if sampleID == "" {
		return nil, fmt.Errorf("sampleId required")
	}
	database.Exec(`UPDATE samples SET status='collected', sealed=TRUE, current_holder_id=$1, updated_at=NOW() WHERE sample_id=$2`, workerID, sampleID)
	database.Exec(`UPDATE assignments SET status='completed', updated_at=NOW() WHERE sample_id=$1 AND worker_id=$2 AND kind='collection' AND status='accepted'`, sampleID, workerID)
	return s.GetSampleLifecycle(database, sampleID)
}

func (s *Service) RegisterPreSealedSample(database *sql.DB, workerID string, body map[string]interface{}, role string) (map[string]interface{}, error) {
	sampleID := uid()
	stID, _ := body["sampleTypeId"].(string)
	originType, _ := body["originType"].(string)
	originNodeID, _ := body["originNodeId"].(string)
	deadlineStr, _ := body["deliveryDeadline"].(string)

	if originType == "home" {
		return nil, fmt.Errorf("pre-sealed samples must originate from clinic or node")
	}

	deadline, _ := time.Parse(time.RFC3339, deadlineStr)
	if deadline.IsZero() {
		deadline = time.Now().Add(24 * time.Hour)
	}

	st, err := s.GetSampleType(database, stID)
	if err != nil {
		return nil, fmt.Errorf("invalid sample type")
	}

	originLat, originLng := 0.0, 0.0
	if originNodeID != "" {
		database.QueryRow(`SELECT latitude, longitude FROM locations WHERE location_id=$1`, originNodeID).Scan(&originLat, &originLng)
	}

	database.Exec(`INSERT INTO samples (sample_id, request_id, requester_id, origin_lat, origin_lng,
		origin_type, origin_node_id, requested_at, delivery_deadline,
		sample_type_id, container_type, temperature_min_c, temperature_max_c,
		status, sealed, serviceability, current_holder_id, latitude, longitude)
		VALUES ($1, $2, $3, $4, $5, $6, $7, NOW(), $8, $9, $10, $11, $12, 'collected', TRUE, 'unchecked', $3, $4, $5)`,
		sampleID, uid(), workerID, originLat, originLng,
		ns(originType), ns(originNodeID), deadline,
		stID, st.ContainerType, st.TemperatureMinC, st.TemperatureMaxC)

	return s.GetSampleLifecycle(database, sampleID)
}

func (s *Service) CreateHandoff(database *sql.DB, fromWorkerID string, body map[string]interface{}, role string) (map[string]interface{}, error) {
	sampleID, _ := body["sampleId"].(string)
	toWorkerID, _ := body["toWorkerId"].(string)
	journeyID, _ := body["journeyId"].(string)
	handoffID := uid()
	database.Exec(`INSERT INTO handoffs (handoff_id, sample_id, journey_id, from_worker_id, to_worker_id, status)
		VALUES ($1, $2, $3, $4, $5, 'pending')`, handoffID, sampleID, journeyID, fromWorkerID, toWorkerID)
	database.Exec(`UPDATE samples SET pending_handoff_id=$1, updated_at=NOW() WHERE sample_id=$2`, handoffID, sampleID)
	return map[string]interface{}{"handoffId": handoffID, "status": "pending"}, nil
}

func (s *Service) ConfirmHandoff(database *sql.DB, workerID string, body map[string]interface{}, role string) (map[string]interface{}, error) {
	handoffID, _ := body["handoffId"].(string)
	side, _ := body["side"].(string)

	var fromWorker, toWorker, status string
	var senderConfirmed, receiverConfirmed bool
	var sampleID string
	err := database.QueryRow(`SELECT sample_id, from_worker_id, to_worker_id, status, sender_confirmed, receiver_confirmed
		FROM handoffs WHERE handoff_id=$1`, handoffID).Scan(&sampleID, &fromWorker, &toWorker, &status, &senderConfirmed, &receiverConfirmed)
	if err != nil {
		return nil, fmt.Errorf("handoff not found")
	}
	if status == "completed" {
		return nil, fmt.Errorf("handoff already completed")
	}

	switch side {
	case "sender":
		if workerID != fromWorker {
			return nil, fmt.Errorf("not the sender")
		}
		database.Exec(`UPDATE handoffs SET sender_confirmed=TRUE, sender_confirmed_at=NOW(),
			status=CASE WHEN receiver_confirmed THEN 'completed' ELSE 'sender_confirmed' END,
			completed_at=CASE WHEN receiver_confirmed THEN NOW() ELSE NULL END WHERE handoff_id=$1`, handoffID)
		if receiverConfirmed {
			database.Exec(`UPDATE samples SET current_holder_id=$1, pending_handoff_id=NULL, status='in_transit', updated_at=NOW() WHERE sample_id=$2`, toWorker, sampleID)
		}
	case "receiver":
		if workerID != toWorker {
			return nil, fmt.Errorf("not the receiver")
		}
		database.Exec(`UPDATE handoffs SET receiver_confirmed=TRUE, receiver_confirmed_at=NOW(),
			status=CASE WHEN sender_confirmed THEN 'completed' ELSE 'receiver_confirmed' END,
			completed_at=CASE WHEN sender_confirmed THEN NOW() ELSE NULL END WHERE handoff_id=$1`, handoffID)
		if senderConfirmed {
			database.Exec(`UPDATE samples SET current_holder_id=$1, pending_handoff_id=NULL, status='in_transit', updated_at=NOW() WHERE sample_id=$2`, toWorker, sampleID)
		}
	default:
		return nil, fmt.Errorf("side must be 'sender' or 'receiver'")
	}

	return map[string]interface{}{"handoffId": handoffID, "status": "confirmed"}, nil
}

func (s *Service) ConfirmLaboratoryReceipt(database *sql.DB, workerID string, body map[string]interface{}, role string) (map[string]interface{}, error) {
	sampleID, _ := body["sampleId"].(string)
	labID, _ := body["laboratoryId"].(string)
	database.Exec(`UPDATE samples SET status='received', received_laboratory_id=$1, current_holder_id=NULL, updated_at=NOW() WHERE sample_id=$2`, labID, sampleID)
	database.Exec(`UPDATE assignments SET status='completed', updated_at=NOW() WHERE sample_id=$1 AND laboratory_id=$2 AND kind='laboratory' AND status='accepted'`, sampleID, labID)
	return s.GetSampleLifecycle(database, sampleID)
}

func (s *Service) ConfigureLaboratoryAcceptance(database *sql.DB, body map[string]interface{}, role string) error {
	labID, _ := body["laboratoryId"].(string)
	if sampleTypes, ok := body["acceptedSampleTypeIds"].([]interface{}); ok {
		database.Exec(`DELETE FROM laboratory_sample_types WHERE location_id=$1`, labID)
		for _, st := range sampleTypes {
			if sts, ok := st.(string); ok {
				database.Exec(`INSERT INTO laboratory_sample_types (location_id, sample_type_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, labID, sts)
			}
		}
	}
	if capacity, ok := body["capacity"].(map[string]interface{}); ok {
		s.ConfigureCapacity(database, "location", labID, capacity)
	}
	return nil
}

func (s *Service) RecordException(database *sql.DB, workerID string, body map[string]interface{}, role string) (map[string]interface{}, error) {
	sampleID, _ := body["sampleId"].(string)
	reason, _ := body["reason"].(string)
	database.Exec(`UPDATE samples SET status='exception', exception_reason=$1, exception_observed_at=NOW(), exception_recorded_by=$2, updated_at=NOW() WHERE sample_id=$3`,
		reason, workerID, sampleID)
	return s.GetSampleLifecycle(database, sampleID)
