func (s *Service) GetWorkerLocations(db_ *sql.DB) ([]map[string]interface{}, error) {
	rows, err := db_.Query(`SELECT user_id, username, full_name, latitude, longitude, location_recorded_at,
		ARRAY(SELECT role FROM user_roles WHERE user_id = users.user_id) as roles
		FROM users WHERE latitude != 0 AND longitude != 0 AND active = TRUE`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var workers []map[string]interface{}
	for rows.Next() {
		var id, uname, fname string
		var lat, lng float64
		var recAt sql.NullTime
		var roles []string
		rows.Scan(&id, &uname, &fname, &lat, &lng, &recAt, &roles)
		w := map[string]interface{}{
			"userId":   id,
			"username": uname,
			"fullName": fname,
			"latitude": lat,
			"longitude": lng,
			"roles":   roles,
		}
		if recAt.Valid {
			w["locationRecordedAt"] = recAt.Time
		}
		workers = append(workers, w)
	}
	return workers, nil
}

func (s *Service) RecordWorkerLocation(db_ *sql.DB, workerID string, lat, lng float64) error {
	_, err := db_.Exec(`UPDATE users SET latitude=$1, longitude=$2, location_recorded_at=NOW() WHERE user_id=$3`, lat, lng, workerID)
	return err
}

// ── Map Data ──

func (s *Service) GetMapData(db_ *sql.DB) (map[string]interface{}, error) {
	locs, _ := s.GetLocations(db_)
	conns, _ := s.GetConnections(db_)
	workers, _ := s.GetWorkerLocations(db_)

	// Get samples with locations
	sRows, err := db_.Query(`SELECT s.sample_id, s.status, s.latitude, s.longitude, s.location_recorded_at, s.sample_type_id
		FROM samples s WHERE s.latitude != 0 AND s.longitude != 0`)
	if err != nil {
		return nil, err
	}
	defer sRows.Close()

	var samples []map[string]interface{}
	for sRows.Next() {
		var id, status, stID string
		var lat, lng float64
		var recAt sql.NullTime
		sRows.Scan(&id, &status, &lat, &lng, &recAt, &stID)
		sm := map[string]interface{}{
			"sampleId":     id,
			"status":       status,
			"latitude":     lat,
			"longitude":    lng,
			"sampleTypeId": stID,
		}
		if recAt.Valid {
			sm["locationRecordedAt"] = recAt.Time
			sm["locationStale"] = time.Since(recAt.Time) > 15*time.Minute
		}
		samples = append(samples, sm)
	}

	return map[string]interface{}{
		"locations":  locs,
		"connections": conns,
		"workers":    workers,
		"samples":    samples,
	}, nil
}

