observation.old_content:
package service

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"math"
	"strings"
	"sync"
	"time"

	"lab-sample-system/internal/auth"
	"lab-sample-system/internal/model"

	"github.com/google/uuid"
)

type Service struct {
	mu sync.RWMutex
}

func New() *Service {
	return &Service{}
}

func uid() string {
	return uuid.New().String()[:8]
}

// ── Auth ──

func (s *Service) Authenticate(database *sql.DB, username, password string) (*model.AuthResponse, *model.ErrorResponse) {
	var user model.User
	err := database.QueryRow(`SELECT u.user_id, u.username, u.password_hash, u.full_name, u.email, u.phone, u.active,
		u.assigned_location_id, u.available, u.capacity_units, u.decline_count, u.latitude, u.longitude
		FROM users u WHERE u.username = $1`, username).Scan(
		&user.UserID, &user.Username, &user.PasswordHash, &user.FullName, &user.Email, &user.Phone,
		&user.Active, &user.AssignedLocationID, &user.Available, &user.CapacityUnits, &user.DeclineCount,
		&user.LatestLatitude, &user.LatestLongitude)
	if err != nil {
		return nil, &model.ErrorResponse{Error: "invalid credentials", Code: "UNAUTHORIZED"}
	}
	if !user.Active {
		return nil, &model.ErrorResponse{Error: "account deactivated", Code: "FORBIDDEN"}
	}
	if !auth.CheckPassword(user.PasswordHash, password) {
		return nil, &model.ErrorResponse{Error: "invalid credentials", Code: "UNAUTHORIZED"}
	}

	rows, err := database.Query(`SELECT role FROM user_roles WHERE user_id = $1`, user.UserID)
	if err != nil {
		return nil, &model.ErrorResponse{Error: "internal error", Code: "INTERNAL"}
	}
	defer rows.Close()

	var roles []model.Role
	for rows.Next() {
		var r string
		rows.Scan(&r)
		roles = append(roles, model.Role(r))
	}

	token, _, err := auth.GenerateToken(user.UserID, user.Username, roleStrings(roles))
	if err != nil {
		return nil, &model.ErrorResponse{Error: "internal error", Code: "INTERNAL"}
	}

	return &model.AuthResponse{
		Token:    token,
		UserID:   user.UserID,
		Roles:    roles,
		FullName: user.FullName,
	}, nil
}

func roleStrings(roles []model.Role) []string {
	s := make([]string, len(roles))
	for i, r := range roles {
		s[i] = string(r)
	}
	return s
}

// ── Users ──

func (s *Service) GetUser(db_ *sql.DB, userID string) (*model.User, error) {
	var u model.User
	err := db_.QueryRow(`SELECT u.user_id, u.username, u.full_name, u.email, u.phone, u.active,
		u.assigned_location_id, u.available, u.capacity_units, u.decline_count,
		u.latitude, u.longitude, u.location_recorded_at
		FROM users u WHERE u.user_id = $1`, userID).Scan(
		&u.UserID, &u.Username, &u.FullName, &u.Email, &u.Phone, &u.Active,
		&u.AssignedLocationID, &u.Available, &u.CapacityUnits, &u.DeclineCount,
		&u.LatestLatitude, &u.LatestLongitude, &u.LocationRecordedAt)
	if err != nil {
		return nil, err
	}

	// Roles
	rows, err := db_.Query(`SELECT role FROM user_roles WHERE user_id = $1`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var r string
		rows.Scan(&r)
		u.Roles = append(u.Roles, model.Role(r))
	}

	// Certifications
	cRows, err := db_.Query(`SELECT code, active, expires_at FROM user_certifications WHERE user_id = $1`, userID)
	if err != nil {
		return nil, err
	}
	defer cRows.Close()
	for cRows.Next() {
		var c model.Certification
		cRows.Scan(&c.Code, &c.Active, &c.ExpiresAt)
		u.Certifications = append(u.Certifications, c)
	}

	// Qualifications
	qRows, err := db_.Query(`SELECT qualification FROM user_qualifications WHERE user_id = $1`, userID)
	if err != nil {
		return nil, err
	}
	defer qRows.Close()
	for qRows.Next() {
		var q string
		qRows.Scan(&q)
		u.Qualifications = append(u.Qualifications, q)
	}

	if u.LatestLatitude != nil {
		u.LatestLatitude = u.LatestLatitude
	}

	return &u, nil
}

func (s *Service) CreateUser(database *sql.DB, req map[string]interface{}) (*model.User, error) {
	userID := uid()
	username, _ := req["username"].(string)
	password, _ := req["password"].(string)
	fullName, _ := req["fullName"].(string)
	email, _ := req["email"].(string)
	phone, _ := req["phone"].(string)

	hash, err := auth.HashPassword(password)
	if err != nil {
		return nil, err
	}

	_, err = database.Exec(`INSERT INTO users (user_id, username, password_hash, full_name, email, phone) VALUES ($1, $2, $3, $4, $5, $6)`,
		userID, username, hash, fullName, email, phone)
	if err != nil {
		return nil, err
	}

	if roles, ok := req["roles"].([]interface{}); ok {
		for _, r := range roles {
			if rs, ok := r.(string); ok {
				database.Exec(`INSERT INTO user_roles (user_id, role) VALUES ($1, $2) ON CONFLICT DO NOTHING`, userID, rs)
			}
		}
	}

	if certs, ok := req["certifications"].([]interface{}); ok {
		for _, c := range certs {
			if cm, ok := c.(map[string]interface{}); ok {
				code, _ := cm["code"].(string)
				if code != "" {
					database.Exec(`INSERT INTO user_certifications (user_id, code) VALUES ($1, $2) ON CONFLICT DO NOTHING`, userID, code)
				}
			}
		}
	}

	if quals, ok := req["qualifications"].([]interface{}); ok {
		for _, q := range quals {
			if qs, ok := q.(string); ok {
				database.Exec(`INSERT INTO user_qualifications (user_id, qualification) VALUES ($1, $2) ON CONFLICT DO NOTHING`, userID, qs)
			}
		}
	}

	if locID, ok := req["assignedLocationId"].(string); ok && locID != "" {
		database.Exec(`UPDATE users SET assigned_location_id = $1 WHERE user_id = $2`, locID, userID)
	}

	return s.GetUser(database, userID)
}

// ── Locations ──

func (s *Service) CreateLocation(db_ *sql.DB, req map[string]interface{}) (*model.Location, error) {
	locID, _ := req["locationId"].(string)
	if locID == "" {
		locID = uid()
	}
	name, _ := req["name"].(string)
	lat, lng := 0.0, 0.0
	if coord, ok := req["coordinate"].(map[string]interface{}); ok {
		if v, ok := coord["latitude"].(float64); ok {
			lat = v
		}
		if v, ok := coord["longitude"].(float64); ok {
			lng = v
		}
	}

	coverageKm := 5.0
	if v, ok := req["coverageKm"].(float64); ok {
		coverageKm = v
	}
	handlingMin := 0
	if v, ok := req["handlingMinutes"].(float64); ok {
		handlingMin = int(v)
	}
	active := true
	if v, ok := req["active"].(bool); ok {
		active = v
	}

	_, err := db_.Exec(`INSERT INTO locations (location_id, name, latitude, longitude, coverage_km, handling_minutes, active)
		VALUES ($1, $2, $3, $4, $5, $6, $7) ON CONFLICT (location_id) DO UPDATE SET name=$2, latitude=$3, longitude=$4, coverage_km=$5, handling_minutes=$6, active=$7`,
		locID, name, lat, lng, coverageKm, handlingMin, active)
	if err != nil {
		return nil, err
	}

	// Reset all function flags
	db_.Exec(`UPDATE locations SET fn_collection_point=FALSE, fn_transfer_point=FALSE, fn_hub=FALSE, fn_laboratory=FALSE WHERE location_id=$1`, locID)

	// functions comes as []string in contract
	if funcs, ok := req["functions"].([]interface{}); ok {
		for _, f := range funcs {
			if fs, ok := f.(string); ok {
				switch fs {
				case "collection_point":
					db_.Exec(`UPDATE locations SET fn_collection_point=TRUE WHERE location_id=$1`, locID)
				case "transfer_point":
					db_.Exec(`UPDATE locations SET fn_transfer_point=TRUE WHERE location_id=$1`, locID)
				case "hub":
					db_.Exec(`UPDATE locations SET fn_hub=TRUE WHERE location_id=$1`, locID)
				case "laboratory":
					db_.Exec(`UPDATE locations SET fn_laboratory=TRUE WHERE location_id=$1`, locID)
				}
			}
		}
	}

	if capacity, ok := req["capacity"].(map[string]interface{}); ok {
		s.ConfigureCapacity(db_, "location", locID, capacity)
	}

	if sampleTypes, ok := req["acceptedSampleTypeIds"].([]interface{}); ok {
		for _, st := range sampleTypes {
			if sts, ok := st.(string); ok {
				db_.Exec(`INSERT INTO laboratory_sample_types (location_id, sample_type_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, locID, sts)
			}
		}
	}

	return s.GetLocation(db_, locID)
}

func (s *Service) GetLocation(db_ *sql.DB, locID string) (*model.Location, error) {
	var l model.Location
	err := db_.QueryRow(`SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active,
		fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory
		FROM locations WHERE location_id = $1`, locID).Scan(
		&l.LocationID, &l.Name, &l.Coordinate.Latitude, &l.Coordinate.Longitude,
		&l.CoverageKm, &l.HandlingMinutes, &l.Active,
		&l.Functions.CollectionPoint, &l.Functions.TransferPoint, &l.Functions.Hub, &l.Functions.Laboratory)
	return &l, err
}

func (s *Service) GetLocations(db_ *sql.DB) ([]model.OperationsLocation, error) {
	rows, err := db_.Query(`SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active,
		fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var locs []model.OperationsLocation
	for rows.Next() {
		var l model.OperationsLocation
		rows.Scan(&l.ID, &l.Name, &l.Coordinate.Latitude, &l.Coordinate.Longitude,
			&l.CoverageKm, &l.HandlingMinutes, &l.Active,
			&l.Functions.CollectionPoint, &l.Functions.TransferPoint, &l.Functions.Hub, &l.Functions.Laboratory)
		l.LocationID = l.ID
		l.Capacity = s.GetCapacity(db_, "location", l.ID)
		l.AcceptedSampleTypeIDs = s.getLocationSampleTypes(db_, l.ID)
		locs = append(locs, l)
	}
	return locs, nil
}

func (s *Service) getLocationSampleTypes(db_ *sql.DB, locID string) []string {
	rows, err := db_.Query(`SELECT sample_type_id FROM laboratory_sample_types WHERE location_id = $1`, locID)
	if err != nil {
		return nil
	}
	defer rows.Close()
	var ids []string
	for rows.Next() {
		var id string
		rows.Scan(&id)
		ids = append(ids, id)
	}
	return ids
}

// ── Connections ──

func (s *Service) CreateConnection(db_ *sql.DB, req map[string]interface{}) (*model.Connection, error) {
	connID, _ := req["connectionId"].(string)
	if connID == "" {
		connID = uid()
	}
	from, _ := req["fromLocationId"].(string)
	to, _ := req["toLocationId"].(string)
	travelMin, _ := req["travelMinutes"].(float64)
	cost, _ := req["costUnits"].(float64)
	cooled, _ := req["cooled"].(bool)

	_, err := db_.Exec(`INSERT INTO connections (connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled)
		VALUES ($1, $2, $3, $4, $5, $6) ON CONFLICT (connection_id) DO UPDATE SET from_location_id=$2, to_location_id=$3, travel_minutes=$4, cost_units=$5, cooled=$6`,
		connID, from, to, int(travelMin), cost, cooled)
	if err != nil {
		return nil, err
	}

	if capacity, ok := req["capacity"].(map[string]interface{}); ok {
		s.ConfigureCapacity(db_, "connection", connID, capacity)
	}

	return s.GetConnection(db_, connID)
}

func (s *Service) GetConnection(db_ *sql.DB, connID string) (*model.Connection, error) {
	var c model.Connection
	err := db_.QueryRow(`SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active
		FROM connections WHERE connection_id = $1`, connID).Scan(
		&c.ConnectionID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active)
	return &c, err
}

func (s *Service) GetConnections(db_ *sql.DB) ([]model.OperationsConnection, error) {
	rows, err := db_.Query(`SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active FROM connections`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var conns []model.OperationsConnection
	for rows.Next() {
		var c model.OperationsConnection
		rows.Scan(&c.ConnectionID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active)
		c.ID = c.ConnectionID
		c.Capacity = s.GetCapacity(db_, "connection", c.ConnectionID)
		conns = append(conns, c)
	}
	return conns, nil
}

// ── Capacity ──

func (s *Service) ConfigureCapacity(db_ *sql.DB, entityType, entityID string, cap map[string]interface{}) error {
	reg, _ := cap["regularCapacity"].(float64)
	cooled, _ := cap["cooledCapacity"].(float64)
	_, err := db_.Exec(`INSERT INTO capacity (entity_type, entity_id, capacity_units, cooled_capacity_units)
		VALUES ($1, $2, $3, $4) ON CONFLICT (entity_type, entity_id) DO UPDATE SET capacity_units=$3, cooled_capacity_units=$4`,
		entityType, entityID, int(reg), int(cooled))
	return err
}

func (s *Service) GetCapacity(db_ *sql.DB, entityType, entityID string) *model.Capacity {
	var c model.Capacity
	err := db_.QueryRow(`SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM capacity WHERE entity_type=$1 AND entity_id=$2`, entityType, entityID).Scan(
		&c.CapacityUnits, &c.ReservedUnits, &c.CooledCapacityUnits, &c.CooledReservedUnits)
	if err != nil {
		return nil
	}
	c.AvailableUnits = c.CapacityUnits - c.ReservedUnits
	c.CooledAvailableUnits = c.CooledCapacityUnits - c.CooledReservedUnits
	if c.AvailableUnits < 0 {
		c.AvailableUnits = 0
	}
	return &c
}

// ── Sample types ──

func (s *Service) CreateSampleType(db_ *sql.DB, req map[string]interface{}) (*model.SampleType, error) {
	stID, _ := req["sampleTypeId"].(string)
	if stID == "" {
		stID = uid()
	}
	name, _ := req["name"].(string)
	container, _ := req["containerType"].(string)
	minT, _ := req["temperatureMinC"].(float64)
	maxT, _ := req["temperatureMaxC"].(float64)
	cooled, _ := req["requiresCooledRoute"].(bool)
	batching, _ := req["batchingAllowed"].(bool)
	qualRequired, _ := req["qualifiedCollectorRequired"].(bool)
	qual, _ := req["requiredQualification"].(string)

	_, err := db_.Exec(`INSERT INTO sample_types (sample_type_id, name, qualified_collector_required, required_qualification,
		container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9) ON CONFLICT (sample_type_id) DO UPDATE SET name=$2`,
		stID, name, qualRequired, qual, container, minT, maxT, cooled, batching)
	if err != nil {
		return nil, err
	}

	if incompatible, ok := req["incompatibleSampleTypes"].([]interface{}); ok {
		db_.Exec(`DELETE FROM sample_type_incompatibilities WHERE sample_type_id = $1`, stID)
		for _, inc := range incompatible {
			if s, ok := inc.(string); ok {
				db_.Exec(`INSERT INTO sample_type_incompatibilities (sample_type_id, incompatible_type_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, stID, s)
			}
		}
	}

	return s.GetSampleType(db_, stID)
}

func (s *Service) GetSampleType(db_ *sql.DB, stID string) (*model.SampleType, error) {
	var st model.SampleType
	err := db_.QueryRow(`SELECT sample_type_id, name, qualified_collector_required, required_qualification,
		container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed
		FROM sample_types WHERE sample_type_id = $1`, stID).Scan(
		&st.SampleTypeID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification,
		&st.ContainerType, &st.TemperatureMinC, &st.TemperatureMaxC, &st.RequiresCooledRoute, &st.BatchingAllowed)

	rows, err := db_.Query(`SELECT incompatible_type_id FROM sample_type_incompatibilities WHERE sample_type_id = $1`, stID)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var id string
			rows.Scan(&id)
			st.IncompatibleSampleTypes = append(st.IncompatibleSampleTypes, id)
		}
	}
	return &st, err
}

// ── Serviceability ──

func (s *Service) CheckServiceability(db_ *sql.DB, req model.ServiceabilityCheckRequest) *model.ServiceabilityResponse {
	// Find nearest active collection node within coverage
	originType := model.OriginNode
	if req.OriginType != nil {
		originType = *req.OriginType
	}

	// For home/clinic origins, find nearest active collection point
	rows, err := db_.Query(`SELECT location_id, name, latitude, longitude, coverage_km FROM locations
		WHERE active = TRUE AND fn_collection_point = TRUE`)
	if err != nil {
		return &model.ServiceabilityResponse{Serviceable: false, Reason: "internal error"}
	}
	defer rows.Close()

	var nearest *model.ServiceabilityRegion
	minDist := math.MaxFloat64
	for rows.Next() {
		var r model.ServiceabilityRegion
		rows.Scan(&r.LocationID, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm)
		dist := haversine(req.Origin.Latitude, req.Origin.Longitude, r.Latitude, r.Longitude)
		if dist < minDist {
			minDist = dist
			nearest = &r
		}
	}

	if originType != model.OriginNode && nearest != nil && minDist > nearest.CoverageKm {
		return &model.ServiceabilityResponse{Serviceable: false, Reason: "origin outside coverage area"}
	}

	// Check there's an active laboratory that accepts this sample type
	var labCount int
	db_.QueryRow(`SELECT COUNT(*) FROM locations l
		JOIN laboratory_sample_types lst ON l.location_id = lst.location_id
		WHERE l.active = TRUE AND l.fn_laboratory = TRUE AND lst.sample_type_id = $1`, req.SampleTypeID).Scan(&labCount)
	if labCount == 0 {
		return &model.ServiceabilityResponse{Serviceable: false, Reason: "no accepting laboratory"}
	}

	// Check valid route exists
	hasRoute := s.hasValidRoute(db_, req)
	if !hasRoute {
		return &model.ServiceabilityResponse{Serviceable: false, Reason: "no valid route"}
	}

	// Check capacity
	if !s.hasCapacity(db_, req) {
		return &model.ServiceabilityResponse{Serviceable: false, Reason: "insufficient capacity"}
	}

	// Check deadline can be met
	if !s.canMeetDeadline(db_, req) {
		return &model.ServiceabilityResponse{Serviceable: false, Reason: "cannot meet deadline"}
	}

	return &model.ServiceabilityResponse{Serviceable: true}
}

func (s *Service) hasValidRoute(db_ *sql.DB, req model.ServiceabilityCheckRequest) bool {
	// A simple BFS to check if there's a path from any collection point to an accepting lab
	// through active connections
	rows, err := db_.Query(`SELECT DISTINCT l.location_id FROM locations l
		WHERE l.active = TRUE AND l.fn_collection_point = TRUE`)
	if err != nil {
		return false
	}
	defer rows.Close()

	targetLabs := s.getAcceptingLabs(db_, req.SampleTypeID)
	if len(targetLabs) == 0 {
		return false
	}

	for rows.Next() {
		var cpID string
		rows.Scan(&cpID)
		for _, labID := range targetLabs {
			if s.hasPath(db_, cpID, labID) {
				return true
			}
		}
	}
	return false
}

func (s *Service) getAcceptingLabs(db_ *sql.DB, stID string) []string {
	rows, err := db_.Query(`SELECT l.location_id FROM locations l
		JOIN laboratory_sample_types lst ON l.location_id = lst.location_id
		WHERE l.active = TRUE AND l.fn_laboratory = TRUE AND lst.sample_type_id = $1`, stID)
	if err != nil {
		return nil
	}
	defer rows.Close()
	var ids []string
	for rows.Next() {
		var id string
		rows.Scan(&id)
		ids = append(ids, id)
	}
	return ids
}

func (s *Service) hasPath(db_ *sql.DB, from, to string) bool {
	visited := map[string]bool{}
	queue := []string{from}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		if current == to {
			return true
		}
		if visited[current] {
			continue
		}
		visited[current] = true
		rows, err := db_.Query(`SELECT to_location_id FROM connections WHERE from_location_id=$1 AND active=TRUE`, current)
		if err != nil {
			continue
		}
		defer rows.Close()
		for rows.Next() {
			var next string
			rows.Scan(&next)
			queue = append(queue, next)
		}
	}
	return false
}

func (s *Service) hasCapacity(db_ *sql.DB, req model.ServiceabilityCheckRequest) bool {
	st, err := s.GetSampleType(db_, req.SampleTypeID)
	if err != nil {
		return false
	}
	entityType := "location"
	if st.RequiresCooledRoute {
		// Check for at least one location with cooled capacity
		var count int
		db_.QueryRow(`SELECT COUNT(*) FROM capacity WHERE entity_type=$1 AND cooled_capacity_units > cooled_reserved_units`, entityType).Scan(&count)
		return count > 0
	}
	var count int
	db_.QueryRow(`SELECT COUNT(*) FROM capacity WHERE entity_type=$1 AND capacity_units > reserved_units`, entityType).Scan(&count)
	return count > 0
}

func (s *Service) canMeetDeadline(db_ *sql.DB, req model.ServiceabilityCheckRequest) bool {
	// Simple: just check if there's enough time
	return time.Now().Before(req.DeliveryDeadline)
}

func haversine(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180
	dLng := (lng2 - lng1) * math.Pi / 180
	a := math.Sin(dLat/2)*math.Sin(dLat/2) + math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*math.Sin(dLng/2)*math.Sin(dLng/2)
	return R * 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
}

// ── Serviceability recalculation ──

func (s *Service) RecalculateServiceability(db_ *sql.DB) (*model.ServiceabilitySnapshot, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	var maxVersion int
	db_.QueryRow(`SELECT COALESCE(MAX(version), 0) FROM serviceability_snapshots`).Scan(&maxVersion)
	newVersion := maxVersion + 1

	rows, err := db_.Query(`SELECT location_id, name, latitude, longitude, coverage_km FROM locations WHERE active=TRUE AND fn_collection_point=TRUE`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var regions []model.ServiceabilityRegion
	for rows.Next() {
		var r model.ServiceabilityRegion
		rows.Scan(&r.LocationID, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm)
		regions = append(regions, r)
	}

	snap := model.ServiceabilitySnapshot{
		Version:   newVersion,
		Regions:   regions,
		UpdatedAt: time.Now(),
	}

	data, _ := json.Marshal(snap)
	db_.Exec(`INSERT INTO serviceability_snapshots (version, data, updated_at) VALUES ($1, $2, NOW()) ON CONFLICT (version) DO UPDATE SET data=$2, updated_at=NOW()`, newVersion, data)

	return &snap, nil
}

func (s *Service) GetServiceability(db_ *sql.DB) (*model.ServiceabilitySnapshot, error) {
	var version int
	var data []byte
	err := db_.QueryRow(`SELECT version, data FROM serviceability_snapshots ORDER BY version DESC LIMIT 1`).Scan(&version, &data)
	if err != nil {
		return &model.ServiceabilitySnapshot{Version: 0, Regions: nil, UpdatedAt: time.Now()}, nil
	}
	var snap model.ServiceabilitySnapshot
	json.Unmarshal(data, &snap)
	return &snap, nil
}

