func (s *Service) Authenticate(database *sql.DB, username, password string) (*model.AuthResponse, *model.ErrorResponse) {
	var user model.User
	err := database.QueryRow(`SELECT u.user_id, u.username, u.password_hash, u.full_name, u.email, u.phone, u.active,
		u.assigned_location_id, u.available, u.capacity_units, u.decline_count, u.latitude, u.longitude
		FROM users u WHERE u.username = $1`, username).Scan(
		&user.UserID, &user.Username, &user.PasswordHash, &user.FullName, &user.Email, &user.Phone,
		&user.Active, &user.AssignedLocationID, &user.Available, &user.CapacityUnits, &user.DeclineCount,
		&user.LatestLatitude, &user.LatestLongitude)
	if err != nil {
		return nil, &model.ErrorResponse{Error: "invalid credentials", Code: "UNAUTHORIZED"}
	}
	if !user.Active {
		return nil, &model.ErrorResponse{Error: "account deactivated", Code: "FORBIDDEN"}
	}
	if !auth.CheckPassword(user.PasswordHash, password) {
		return nil, &model.ErrorResponse{Error: "invalid credentials", Code: "UNAUTHORIZED"}
	}

	rows, err := database.Query(`SELECT role FROM user_roles WHERE user_id = $1`, user.UserID)
	if err != nil {
		return nil, &model.ErrorResponse{Error: "internal error", Code: "INTERNAL"}
	}
	defer rows.Close()

	var roles []model.Role
	for rows.Next() {
		var r string
		rows.Scan(&r)
		roles = append(roles, model.Role(r))
	}

	token, _, err := auth.GenerateToken(user.UserID, user.Username, roleStrings(roles))
	if err != nil {
		return nil, &model.ErrorResponse{Error: "internal error", Code: "INTERNAL"}
	}

	return &model.AuthResponse{
		Token:    token,
		UserID:   user.UserID,
		Roles:    roles,
		FullName: user.FullName,
	}, nil
}

