    69	func (h *Handler) switchRole(r *http.Request, role string) (string, error) {
    70		c := middleware.GetClaims(r)
    71		if c == nil {
    72			return "", fmt.Errorf("no claims")
    73		}
    74		for _, rl := range c.Roles {
    75			if rl == role {
    76				token, _, err := auth.GenerateToken(c.UserID, c.Username, c.Roles)
    77				return token, err
    78			}
    79		}
    80		return "", fmt.Errorf("role not assigned")
    81	}
