observation.old_content:
package handler

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"time"

	"lab-sample-system/internal/auth"
	"lab-sample-system/internal/middleware"
	"lab-sample-system/internal/model"
	"lab-sample-system/internal/service"
)

type Handler struct {
	svc *service.Service
	DB  *sql.DB
}

func New(svc *service.Service, db *sql.DB) *Handler {
	return &Handler{svc: svc, DB: db}
}

func (h *Handler) ok(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(map[string]interface{}{"data": data})
}

func (h *Handler) fail(w http.ResponseWriter, status int, msg, code string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(map[string]string{"error": msg, "code": code})
}

func (h *Handler) decode(r *http.Request) (map[string]interface{}, error) {
	var v map[string]interface{}
	if err := json.NewDecoder(r.Body).Decode(&v); err != nil {
		return nil, err
	}
	return v, nil
}

func (h *Handler) uid(r *http.Request) string {
	c := middleware.GetClaims(r)
	if c == nil {
		return "unknown"
	}
	return c.UserID
}

func (h *Handler) role(r *http.Request) string {
	rp := middleware.GetSelectedRole(r)
	if rp != "" {
		return rp
	}
	c := middleware.GetClaims(r)
	if c != nil && len(c.Roles) > 0 {
		return c.Roles[0]
	}
	return "requester"
}

func (h *Handler) audit(r *http.Request, action, etype, eid string, ok bool, det map[string]interface{}) {
	h.svc.WriteAudit(h.DB, h.uid(r), h.role(r), action, etype, eid, ok, det)
}

func (h *Handler) switchRole(r *http.Request, role string) (string, error) {
	c := middleware.GetClaims(r)
	if c == nil {
		return "", fmt.Errorf("no claims")
	}
	for _, rl := range c.Roles {
		if rl == role {
			token, _, err := auth.GenerateToken(c.UserID, c.Username, c.Roles)
			return token, err
		}
	}
	return "", fmt.Errorf("role not assigned")
}

// ── Auth ──

func (h *Handler) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	username, _ := body["username"].(string)
	password, _ := body["password"].(string)
	if username == "" || password == "" {
		h.fail(w, 400, "username and password required", "invalid_json")
		return
	}
	resp, apiErr := h.svc.Authenticate(h.DB, username, password)
	if apiErr != nil {
		h.fail(w, 401, apiErr.Error, "unauthorized")
		return
	}
	h.ok(w, 200, resp)
}

func (h *Handler) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	role, _ := body["role"].(string)
	if role == "" {
		h.fail(w, 400, "role required", "invalid_json")
		return
	}
	token, err := h.switchRole(r, role)
	if err != nil {
		h.fail(w, 403, "role not assigned", "forbidden")
		return
	}
	h.ok(w, 200, map[string]interface{}{"activeRole": role, "roles": []string{role}, "token": token})
}

// ── Users ──

func (h *Handler) CreateUser(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	user, err := h.svc.CreateUser(h.DB, body)
	if err != nil {
		h.fail(w, 409, err.Error(), "concurrent_conflict")
		return
	}
	h.ok(w, 201, user)
}

func (h *Handler) ReadUser(w http.ResponseWriter, r *http.Request) {
	userID := r.PathValue("userId")
	user, err := h.svc.GetUser(h.DB, userID)
	if err != nil {
		h.fail(w, 404, "user not found", "not_found")
		return
	}
	h.ok(w, 200, user)
}

func (h *Handler) UpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	userID, _ := body["userId"].(string)
	if userID == "" {
		h.fail(w, 400, "userId required", "invalid_json")
		return
	}
	if err := h.svc.UpdateUser(h.DB, userID, body); err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	user, _ := h.svc.GetUser(h.DB, userID)
	h.ok(w, 201, user)
}

// ── Location ──

func (h *Handler) CreateLocation(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	loc, err := h.svc.CreateLocation(h.DB, body)
	if err != nil {
		h.fail(w, 409, err.Error(), "concurrent_conflict")
		return
	}
	h.ok(w, 201, loc)
}

func (h *Handler) UpdateLocation(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	locID, _ := body["locationId"].(string)
	if locID == "" {
		h.fail(w, 400, "locationId required", "invalid_json")
		return
	}
	if err := h.svc.UpdateLocation(h.DB, locID, body); err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	loc, _ := h.svc.GetLocation(h.DB, locID)
	h.ok(w, 201, loc)
}

func (h *Handler) SetLocationStatus(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	locID, _ := body["locationId"].(string)
	active, _ := body["active"].(bool)
	if locID == "" {
		h.fail(w, 400, "locationId required", "invalid_json")
		return
	}
	if active {
		h.svc.ActivateEntity(h.DB, "location", locID)
	} else {
		h.svc.DeactivateEntity(h.DB, "location", locID)
	}
	h.ok(w, 200, map[string]interface{}{"locationId": locID, "active": active})
}

func (h *Handler) SetLocationFunctionStatus(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	locID, _ := body["locationId"].(string)
	fn, _ := body["function"].(string)
	fnActive, _ := body["active"].(bool)
	if locID == "" || fn == "" {
		h.fail(w, 400, "locationId and function required", "invalid_json")
		return
	}
	if err := h.svc.SetLocationFunction(h.DB, locID, fn, fnActive); err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 200, map[string]interface{}{"locationId": locID, "function": fn, "active": fnActive})
}

// ── Connection ──

func (h *Handler) CreateConnection(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	conn, err := h.svc.CreateConnection(h.DB, body)
	if err != nil {
		h.fail(w, 409, err.Error(), "concurrent_conflict")
		return
	}
	h.ok(w, 201, conn)
}

func (h *Handler) SetConnectionStatus(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	connID, _ := body["connectionId"].(string)
	active, _ := body["active"].(bool)
	if connID == "" {
		h.fail(w, 400, "connectionId required", "invalid_json")
		return
	}
	if active {
		h.svc.ActivateEntity(h.DB, "connection", connID)
	} else {
		h.svc.DeactivateEntity(h.DB, "connection", connID)
	}
	h.ok(w, 200, map[string]interface{}{"connectionId": connID, "active": active})
}

// ── Sample Type ──

func (h *Handler) CreateSampleType(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	st, err := h.svc.CreateSampleType(h.DB, body)
	if err != nil {
		h.fail(w, 409, err.Error(), "concurrent_conflict")
		return
	}
	h.ok(w, 201, st)
}

func (h *Handler) UpdateSampleType(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	stID, _ := body["sampleTypeId"].(string)
	if stID == "" {
		h.fail(w, 400, "sampleTypeId required", "invalid_json")
		return
	}
	if err := h.svc.UpdateSampleType(h.DB, body); err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	st, _ := h.svc.GetSampleType(h.DB, stID)
	h.ok(w, 201, st)
}

// ── Capacity ──

func (h *Handler) ConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	resID, _ := body["resourceId"].(string)
	if resID == "" {
		h.fail(w, 400, "resourceId required", "invalid_json")
		return
	}
	resType := "location"
	if rt, _ := body["resourceType"].(string); rt != "" {
		resType = rt
	}
	h.svc.ConfigureCapacity(h.DB, resType, resID, body)
	cap := h.svc.GetCapacity(h.DB, resType, resID)
	if cap == nil {
		cap = &model.Capacity{}
	}
	h.ok(w, 200, map[string]interface{}{
		"resourceId":          resID,
		"capacityUnits":       cap.CapacityUnits,
		"cooledCapacityUnits": cap.CooledCapacityUnits,
	})
}

// ── Serviceability ──

func (h *Handler) CheckServiceability(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	req := model.ServiceabilityCheckRequest{}
	if o, ok := body["origin"].(map[string]interface{}); ok {
		req.Origin.Latitude, _ = o["latitude"].(float64)
		req.Origin.Longitude, _ = o["longitude"].(float64)
	}
	if ot, ok := body["originType"].(string); ok && ot != "" {
		v := model.OriginType(ot)
		req.OriginType = &v
	}
	if oni, ok := body["originNodeId"].(string); ok && oni != "" {
		req.OriginNodeID = &oni
	}
	req.SampleTypeID, _ = body["sampleTypeId"].(string)
	if t, ok := body["requestedAt"].(string); ok {
		parsed, _ := time.Parse(time.RFC3339, t)
		req.RequestedAt = parsed
	}
	if t, ok := body["deliveryDeadline"].(string); ok {
		parsed, _ := time.Parse(time.RFC3339, t)
		req.DeliveryDeadline = parsed
	}
	if t, ok := body["earliestCollectionAt"].(string); ok && t != "" {
		parsed, _ := time.Parse(time.RFC3339, t)
		req.EarliestCollectionAt = &parsed
	}
	if t, ok := body["latestCollectionAt"].(string); ok && t != "" {
		parsed, _ := time.Parse(time.RFC3339, t)
		req.LatestCollectionAt = &parsed
	}
	resp := h.svc.CheckServiceability(h.DB, req)
	h.ok(w, 200, resp)
}

func (h *Handler) ReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	snap, _ := h.svc.GetServiceability(h.DB)
	h.ok(w, 200, snap)
}

// ── Samples ──

func (h *Handler) CreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	sample, err := h.svc.CreateSampleRequest(h.DB, h.uid(r), body)
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 201, sample)
}

func (h *Handler) IngestPresealedSample(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	sample, err := h.svc.RegisterPreSealedSample(h.DB, h.uid(r), body, h.role(r))
	if err != nil {
		h.fail(w, 400, err.Error(), "invalid_json")
		return
	}
	h.ok(w, 201, sample)
}

func (h *Handler) CollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	sample, err := h.svc.CollectAndSealSample(h.DB, h.uid(r), body, h.role(r))
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 201, sample)
}

func (h *Handler) ReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	sid, _ := body["sampleId"].(string)
	if sid == "" {
		h.fail(w, 400, "sampleId required", "invalid_json")
		return
	}
	sm, err := h.svc.GetSampleLifecycle(h.DB, sid)
	if err != nil {
		h.fail(w, 404, "sample not found", "not_found")
		return
	}
	h.ok(w, 200, sm)
}

func (h *Handler) ReadSampleState(w http.ResponseWriter, r *http.Request) {
	sid := r.PathValue("sampleId")
	sm, err := h.svc.GetSampleLifecycle(h.DB, sid)
	if err != nil {
		h.fail(w, 404, "sample not found", "not_found")
		return
	}
	h.ok(w, 200, sm)
}

// ── Handoff ──

func (h *Handler) InitiateHandoff(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	result, err := h.svc.CreateHandoff(h.DB, h.uid(r), body, h.role(r))
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 201, result)
}

func (h *Handler) ConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	result, err := h.svc.ConfirmHandoff(h.DB, h.uid(r), body, h.role(r))
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 201, result)
}

// ── Laboratory ──

func (h *Handler) ConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	sm, err := h.svc.ConfirmLaboratoryReceipt(h.DB, h.uid(r), body, h.role(r))
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 201, sm)
}

func (h *Handler) ConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	labID, _ := body["laboratoryId"].(string)
	stID, _ := body["sampleTypeId"].(string)
	accepts, _ := body["accepts"].(bool)
	if err := h.svc.ConfigureLaboratoryAcceptance(h.DB, labID, stID, accepts); err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 200, map[string]interface{}{
		"acceptanceId": labID + "-" + stID,
		"accepts":      accepts,
	})
}

func (h *Handler) RecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	sampleID, _ := body["sampleId"].(string)
	reason, _ := body["reason"].(string)
	labID, _ := body["laboratoryId"].(string)
	sm, err := h.svc.RecordException(h.DB, h.uid(r), sampleID, reason, labID)
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 201, sm)
}

func (h *Handler) RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	sampleID, _ := body["sampleId"].(string)
	assignmentID, _ := body["assignmentId"].(string)
	locationID, _ := body["locationId"].(string)
	containerType, _ := body["containerType"].(string)
	temp, _ := body["observedTemperatureC"].(float64)
	sm, err := h.svc.RecordHandlingCheckpoint(h.DB, h.uid(r), sampleID, assignmentID, locationID, containerType, temp)
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 201, sm)
}

// ── Worker ──

func (h *Handler) RecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	assignmentID, _ := body["assignmentId"].(string)
	coord, _ := body["coordinate"].(map[string]interface{})
	seq, _ := body["sequence"].(float64)
	recordedAt, _ := body["recordedAt"].(string)
	lat, _ := coord["latitude"].(float64)
	lng, _ := coord["longitude"].(float64)
	if err := h.svc.RecordWorkerLocation(h.DB, h.uid(r), lat, lng); err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 201, map[string]interface{}{
		"assignmentId": assignmentID,
		"coordinate":   coord,
		"sequence":     int(seq),
		"recordedAt":   recordedAt,
	})
}

func (h *Handler) SetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	workerID, _ := body["workerId"].(string)
	available, _ := body["available"].(bool)
	capUnits, _ := body["capacityUnits"].(float64)
	if err := h.svc.SetWorkerAvailability(h.DB, workerID, available, int(capUnits)); err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 200, map[string]interface{}{"workerId": workerID, "available": available, "capacityUnits": int(capUnits)})
}

// ── Work ──

func (h *Handler) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	role, _ := body["role"].(string)
	if role == "" {
		role = h.role(r)
	}
	c := middleware.GetClaims(r)
	allRoles := []string{}
	if c != nil {
		allRoles = c.Roles
	}
	work, err := h.svc.GetRoleWork(h.DB, h.uid(r), role, allRoles)
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 200, work)
}

// ── Assignments ──

func (h *Handler) AcceptAssignment(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	aid, _ := body["assignmentId"].(string)
	if aid == "" {
		h.fail(w, 400, "assignmentId required", "invalid_json")
		return
	}
	result, err := h.svc.AcceptAssignment(h.DB, h.uid(r), aid, h.role(r))
	if err != nil {
		h.fail(w, 404, err.Error(), "not_found")
		return
	}
	h.ok(w, 201, result)
}

func (h *Handler) DeclineAssignment(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	aid, _ := body["assignmentId"].(string)
	if aid == "" {
		h.fail(w, 400, "assignmentId required", "invalid_json")
		return
	}
	result, err := h.svc.DeclineAssignment(h.DB, h.uid(r), aid, h.role(r))
	if err != nil {
		h.fail(w, 404, err.Error(), "not_found")
		return
	}
	h.ok(w, 201, result)
}

func (h *Handler) UpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	aid, _ := body["assignmentId"].(string)
	if aid == "" {
		h.fail(w, 400, "assignmentId required", "invalid_json")
		return
	}
