func (s *Service) RecordHandlingCheckpoint(database *sql.DB, workerID, sampleID, assignmentID, locationID, containerType string, observedTemp float64) (map[string]interface{}, error) {
	checkpointID := fmt.Sprintf("chk-%s-%d", sampleID, time.Now().UnixMilli())
	compliant := true

	var expectedContainer sql.NullString
	var minT, maxT sql.NullFloat64
	var currentStatus string
	err := database.QueryRow(`SELECT container_type, temperature_min_c, temperature_max_c, status FROM samples WHERE sample_id=$1`, sampleID).Scan(&expectedContainer, &minT, &maxT, &currentStatus)
	if err == nil {
		if minT.Valid && maxT.Valid {
			inRange := observedTemp >= minT.Float64 && observedTemp <= maxT.Float64
			containerOk := !expectedContainer.Valid || expectedContainer.String == "" || containerType == expectedContainer.String
			if !inRange || !containerOk {
				compliant = false
				reason := ""
				if !inRange {
					reason = fmt.Sprintf("temperature %.1f outside range [%.1f, %.1f]", observedTemp, minT.Float64, maxT.Float64)
				}
				if !containerOk {
					if reason != "" {
						reason += "; "
					}
					reason += fmt.Sprintf("container %s does not match required %s", containerType, expectedContainer.String)
				}
				database.Exec(`UPDATE samples SET status='exception', exception_reason=$1, exception_observed_at=NOW(), exception_recorded_by=$2 WHERE sample_id=$3`,
					reason, workerID, sampleID)
				currentStatus = "exception"
			}
		}
	}

	return map[string]interface{}{
		"checkpointId": checkpointID,
		"sampleId":     sampleID,
		"compliant":    compliant,
		"sampleStatus": currentStatus,
	}, nil
}

func (s *Service) GetJourneyPlan(database *sql.DB, journeyID, viewerID string, roles []string) (interface{}, error) {
	var jid, status, routeMode string
	var planVersion int
	var estDelivery sql.NullTime
	var totalCost sql.NullFloat64
	var parentJid sql.NullString

	err := database.QueryRow(`SELECT journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units
		FROM journeys WHERE journey_id=$1`, journeyID).Scan(&jid, &parentJid, &planVersion, &routeMode, &status, &estDelivery, &totalCost)
	if err != nil {
		return nil, err
	}

	sRows, err := database.Query(`SELECT sample_id FROM journey_samples WHERE journey_id=$1`, journeyID)
	if err != nil {
		return nil, err
	}
	defer sRows.Close()
	var sampleIDs []string
	for sRows.Next() {
		var sid string
		sRows.Scan(&sid)
		sampleIDs = append(sampleIDs, sid)
	}

	stRows, err := database.Query(`SELECT stop_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude, completed_at
		FROM journey_stops WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	if err != nil {
		return nil, err
	}
	defer stRows.Close()
	var stops []model.JourneyStop
	for stRows.Next() {
		var stop model.JourneyStop
		var completed sql.NullTime
		stRows.Scan(&stop.StopID, &stop.LocationID, &stop.StopType, &stop.Sequence, &stop.EstimatedAt, &stop.DwellMinutes, &stop.Coordinate.Latitude, &stop.Coordinate.Longitude, &completed)
		if completed.Valid {
			stop.CompletedAt = &completed.Time
		}
		stops = append(stops, stop)
	}

	lRows, err := database.Query(`SELECT assignment_id, sequence, status, from_location_id, to_location_id, worker_id, sample_id
		FROM assignments WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	if err != nil {
		return nil, err
	}
	defer lRows.Close()
	var legs []model.JourneyLeg
	var workerIDs []string
	for lRows.Next() {
		var leg model.JourneyLeg
		var from, to, worker, sample sql.NullString
		lRows.Scan(&leg.AssignmentID, &leg.Sequence, &leg.Status, &from, &to, &worker, &sample)
		if from.Valid {
			leg.FromLocationID = from.String
		}
		if to.Valid {
			leg.ToLocationID = to.String
		}
		if worker.Valid {
			leg.WorkerID = &worker.String
			workerIDs = append(workerIDs, worker.String)
		}
		if sample.Valid {
			leg.SampleID = &sample.String
		}
		legs = append(legs, leg)
	}

	isWorker := false
	for _, r := range roles {
		if r == "collection_professional" || r == "delivery_partner" || r == "node_handler" || r == "laboratory_team" {
			isWorker = true
			break
		}
	}

	jp := map[string]interface{}{
		"journeyId":     jid,
		"planVersion":   planVersion,
		"routeMode":     routeMode,
		"status":        status,
		"sampleIds":     sampleIDs,
		"orderedStops":  stops,
	}

	if parentJid.Valid {
		jp["parentJourneyId"] = parentJid.String
	}
	if estDelivery.Valid {
		jp["estimatedDeliveryAt"] = estDelivery.Time
	}
	if totalCost.Valid {
		jp["totalCostUnits"] = totalCost.Float64
	}

	if isWorker {
		jp["legs"] = legs
		jp["assignedWorkerIds"] = workerIDs
	} else {
		var simpleLegs []map[string]string
		for _, l := range legs {
			simpleLegs = append(simpleLegs, map[string]string{
				"assignmentId":   l.AssignmentID,
				"status":         l.Status,
				"fromLocationId": l.FromLocationID,
				"toLocationId":   l.ToLocationID,
			})
		}
		jp["legs"] = simpleLegs
	}

	return jp, nil
}

func (s *Service) CancelJourney(database *sql.DB, journeyID, role string) ([]string, error) {
	rows, err := database.Query(`SELECT sample_id FROM samples WHERE active_journey_id=$1`, journeyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var sampleIDs []string
	for rows.Next() {
		var sid string
		rows.Scan(&sid)
		sampleIDs = append(sampleIDs, sid)
	}
	if sampleIDs == nil {
		sampleIDs = []string{}
	}
	database.Exec(`UPDATE journeys SET status='cancelled', updated_at=NOW() WHERE journey_id=$1`, journeyID)
	database.Exec(`UPDATE assignments SET status='cancelled', updated_at=NOW() WHERE journey_id=$1 AND status != 'completed'`, journeyID)
	database.Exec(`UPDATE samples SET active_journey_id=NULL, status='cancelled', updated_at=NOW() WHERE active_journey_id=$1`, journeyID)
	return sampleIDs, nil
}

func (s *Service) GetTimeline(db_ *sql.DB, entityID string) ([]model.TimelineEntry, error) {
	rows, err := db_.Query(`SELECT audit_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details
		FROM audit_log WHERE entity_id = $1 ORDER BY occurred_at ASC`, entityID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var timeline []model.TimelineEntry
	for rows.Next() {
		var t model.TimelineEntry
		var details []byte
		rows.Scan(&t.EventID, &t.ActorID, &t.Role, &t.Action, &t.EntityType, &t.EntityID, &t.Success, &t.OccurredAt, &details)
		json.Unmarshal(details, &t.Details)
		if t.Details == nil {
			t.Details = map[string]interface{}{}
		}
		timeline = append(timeline, t)
	}
	return timeline, nil
}

// ── Deactivate/Activate ──

func (s *Service) DeactivateEntity(db_ *sql.DB, entityType, entityID string) error {
	switch entityType {
	case "location":
		_, err := db_.Exec(`UPDATE locations SET active = FALSE WHERE location_id = $1`, entityID)
		return err
	case "connection":
		_, err := db_.Exec(`UPDATE connections SET active = FALSE WHERE connection_id = $1`, entityID)
		return err
	case "user":
		_, err := db_.Exec(`UPDATE users SET active = FALSE WHERE user_id = $1`, entityID)
		return err
	default:
		return fmt.Errorf("unknown entity type: %s", entityType)
	}
}

func (s *Service) ActivateEntity(db_ *sql.DB, entityType, entityID string) error {
	switch entityType {
	case "location":
		_, err := db_.Exec(`UPDATE locations SET active = TRUE WHERE location_id = $1`, entityID)
		return err
	case "connection":
		_, err := db_.Exec(`UPDATE connections SET active = TRUE WHERE connection_id = $1`, entityID)
		return err
	case "user":
		_, err := db_.Exec(`UPDATE users SET active = TRUE WHERE user_id = $1`, entityID)
		return err
	default:
		return fmt.Errorf("unknown entity type: %s", entityType)
	}
}

// ── Notifications / Events ──

var eventStore []model.RealtimeEvent
var eventMu sync.Mutex
var eventCounter int64

func (s *Service) PublishEvent(eventType, entityType, entityID string, payload map[string]interface{}) {
	eventMu.Lock()
	defer eventMu.Unlock()
	eventCounter++
	evt := model.RealtimeEvent{
		ID:         eventCounter,
		Type:       eventType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  time.Now(),
	}
	eventStore = append(eventStore, evt)
	if len(eventStore) > 1000 {
		eventStore = eventStore[len(eventStore)-500:]
	}
}

func (s *Service) GetEvents(since int64) []model.RealtimeEvent {
	eventMu.Lock()
	defer eventMu.Unlock()
	if since == 0 && len(eventStore) > 0 {
		since = eventStore[0].ID - 1
	}
	var result []model.RealtimeEvent
	for _, e := range eventStore {
		if e.ID > since {
			result = append(result, e)
		}
	}
	if result == nil {
		result = []model.RealtimeEvent{}
	}
	return result
}

// ── Worker Locations ──

func (s *Service) GetWorkerLocations(db_ *sql.DB) ([]map[string]interface{}, error) {
	rows, err := db_.Query(`SELECT user_id, username, full_name, latitude, longitude, location_recorded_at,
		ARRAY(SELECT role FROM user_roles WHERE user_id = users.user_id) as roles
		FROM users WHERE latitude != 0 AND longitude != 0 AND active = TRUE`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var workers []map[string]interface{}
	for rows.Next() {
		var id, uname, fname string
		var lat, lng float64
		var recAt sql.NullTime
		var roles []string
		rows.Scan(&id, &uname, &fname, &lat, &lng, &recAt, &roles)
		w := map[string]interface{}{
			"userId":   id,
			"username": uname,
			"fullName": fname,
			"latitude": lat,
			"longitude": lng,
			"roles":   roles,
		}
		if recAt.Valid {
			w["locationRecordedAt"] = recAt.Time
		}
		workers = append(workers, w)
	}
	return workers, nil
}

func (s *Service) RecordWorkerLocation(db_ *sql.DB, workerID string, lat, lng float64) error {
	_, err := db_.Exec(`UPDATE users SET latitude=$1, longitude=$2, location_recorded_at=NOW() WHERE user_id=$3`, lat, lng, workerID)
	return err
}

// ── Map Data ──

func (s *Service) GetMapData(db_ *sql.DB) (map[string]interface{}, error) {
	locs, _ := s.GetLocations(db_)
	conns, _ := s.GetConnections(db_)
	workers, _ := s.GetWorkerLocations(db_)

	// Get samples with locations
	sRows, err := db_.Query(`SELECT s.sample_id, s.status, s.latitude, s.longitude, s.location_recorded_at, s.sample_type_id
		FROM samples s WHERE s.latitude != 0 AND s.longitude != 0`)
	if err != nil {
		return nil, err
	}
	defer sRows.Close()

	var samples []map[string]interface{}
	for sRows.Next() {
		var id, status, stID string
		var lat, lng float64
		var recAt sql.NullTime
		sRows.Scan(&id, &status, &lat, &lng, &recAt, &stID)
		sm := map[string]interface{}{
			"sampleId":     id,
			"status":       status,
			"latitude":     lat,
			"longitude":    lng,
			"sampleTypeId": stID,
		}
		if recAt.Valid {
			sm["locationRecordedAt"] = recAt.Time
			sm["locationStale"] = time.Since(recAt.Time) > 15*time.Minute
		}
		samples = append(samples, sm)
	}

	return map[string]interface{}{
		"locations":  locs,
		"connections": conns,
		"workers":    workers,
		"samples":    samples,
	}, nil
}

// ── Collection Plan ──

func (s *Service) GetCollectionPlans(db_ *sql.DB, workerID string) ([]interface{}, error) {
	rows, err := db_.Query(`SELECT a.assignment_id, a.sample_id, a.status, a.sequence,
		s.sample_type_id, s.origin_lat, s.origin_lng, s.delivery_deadline,
		s.earliest_collection_at, s.latest_collection_at
		FROM assignments a JOIN samples s ON a.sample_id = s.sample_id
		WHERE a.worker_id = $1 AND a.kind = 'collection' ORDER BY a.sequence`, workerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var plans []interface{}
	for rows.Next() {
		var aid, sid, status, stID string
		var seq int
		var lat, lng float64
		var deadline time.Time
		var earliest, latest sql.NullTime
		rows.Scan(&aid, &sid, &status, &seq, &stID, &lat, &lng, &deadline, &earliest, &latest)
		plan := map[string]interface{}{
			"assignmentId":     aid,
			"sampleId":         sid,
			"status":           status,
			"sequence":         seq,
			"sampleTypeId":     stID,
			"origin":           map[string]float64{"latitude": lat, "longitude": lng},
			"deliveryDeadline": deadline,
		}
		if earliest.Valid {
			plan["earliestCollectionAt"] = earliest.Time
		}
		if latest.Valid {
			plan["latestCollectionAt"] = latest.Time
		}
		plans = append(plans, plan)
	}
	return plans, nil
}

