	if originNodeID != "" {
		database.QueryRow(`SELECT latitude, longitude FROM locations WHERE location_id=$1`, originNodeID).Scan(&originLat, &originLng)
	}

	database.Exec(`INSERT INTO samples (sample_id, request_id, requester_id, origin_lat, origin_lng,
