func (s *Service) GetNodePlans(db_ *sql.DB, workerID string) ([]interface{}, error) {
	rows, err := db_.Query(`SELECT a.assignment_id, a.sample_id, a.status, a.node_id,
		a.journey_id, a.from_location_id, a.to_location_id
		FROM assignments a WHERE a.worker_id = $1 AND a.kind = 'node' ORDER BY a.created_at`, workerID)
	if err != nil {
