"user":              user,
"locations":         locs,
"sampleTypes":       sTypes,
"connections":       conns,
"serviceabilityURL": "/api/read-serviceability-snapshot",
}, nil
}

func jsonify(m map[string]string) string {
b, _ := json.Marshal(m)
return string(b)
}

