[?2004lpackage middleware

import (
	"context"
	"net/http"
	"strings"

	"lab-sample-system/internal/auth"
	"lab-sample-system/internal/db"
	"lab-sample-system/internal/model"
)

type contextKey string

const ClaimsKey contextKey = "claims"
const SelectedRoleKey contextKey = "selected_role"

func Auth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		if authHeader == "" {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusUnauthorized)
			w.Write([]byte(`{"error":"missing authorization","code":"unauthorized"}`))
			return
		}

		parts := strings.SplitN(authHeader, " ", 2)
		if len(parts) != 2 || !strings.EqualFold(parts[0], "bearer") {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusUnauthorized)
			w.Write([]byte(`{"error":"invalid authorization format","code":"unauthorized"}`))
			return
		}

		claims, err := auth.ParseToken(parts[1])
		if err != nil {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusUnauthorized)
			w.Write([]byte(`{"error":"invalid or expired token","code":"unauthorized"}`))
			return
		}

		// Check JTI blacklist
		var blacklisted bool
		err = db.DB.QueryRow(`SELECT EXISTS(SELECT 1 FROM jwti_blacklist WHERE jti=$1 AND expires_at > NOW())`, claims.ID).Scan(&blacklisted)
		if err == nil && blacklisted {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusUnauthorized)
			w.Write([]byte(`{"error":"token has been revoked","code":"unauthorized"}`))
			return
		}

		role := r.Header.Get("X-Role")
		if role != "" {
			found := false
			for _, rl := range claims.Roles {
				if rl == role {
					found = true
					break
				}
			}
			if !found {
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(http.StatusForbidden)
				w.Write([]byte(`{"error":"role not assigned","code":"forbidden"}`))
				return
			}
		}

		ctx := context.WithValue(r.Context(), ClaimsKey, claims)
		ctx = context.WithValue(ctx, SelectedRoleKey, role)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func GetClaims(r *http.Request) *auth.Claims {
	claims, _ := r.Context().Value(ClaimsKey).(*auth.Claims)
	return claims
}

func GetSelectedRole(r *http.Request) string {
	role, _ := r.Context().Value(SelectedRoleKey).(string)
	return role
}

func Role(allowed ...model.Role) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			claims := GetClaims(r)
			if claims == nil {
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(http.StatusUnauthorized)
				w.Write([]byte(`{"error":"unauthorized","code":"unauthorized"}`))
				return
			}
			for _, a := range allowed {
				for _, rl := range claims.Roles {
					if string(a) == rl {
						next.ServeHTTP(w, r)
						return
					}
				}
			}
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusForbidden)
			w.Write([]byte(`{"error":"forbidden","code":"forbidden"}`))
		})
	}
}

var (
