                    for ct, v in o['requestBody'].get('content', {}).items():
                        schema = v.get('schema', {})
                        if '$ref' in schema:
                            ref = schema['$ref'].split('/')[-1]
                            print(f"  Body: #/components/schemas/{ref}")
                            if ref in c['components']['schemas']:
                                print(f"  Schema: {json.dumps(c['components']['schemas'][ref], indent=4)}")
                        else:
                            print(f"  Body: {json.dumps(schema, indent=4)}")

                # Responses
                for code, resp in o.get('responses', {}).items():
                    if 'content' in resp:
                        for ct, v in resp['content'].items():
                            schema = v.get('schema', {})
                            if '$ref' in schema:
                                ref = schema['$ref'].split('/')[-1]
                                print(f"  Response {code}: #/components/schemas/{ref}")
                            else:
                                print(f"  Response {code}: {json.dumps(schema, indent=4)}")
                    else:
                        print(f"  Response {code}: (no content)")
                break
