    data = json.dumps(body).encode() if body else None
    hdrs = {'Content-Type':'application/json', 'Authorization': 'Bearer '+TOK}
    req = urllib.request.Request(BASE+path, data=data, method=method, headers=hdrs)
    try:
        resp = urllib.request.urlopen(req, timeout=5)
        return resp.status, json.loads(resp.read())
    except urllib.error.HTTPError as e:
        body = json.loads(e.read())
        return e.code, body
    except Exception as e:
        return 0, {"error": str(e)}

def check(name, status, resp, expected_status, required_fields=None, forbidden_fields=None):
    global PASS, FAIL
    ok = True
    # Check status
    if status != expected_status:
        print(f"  FAIL: {name} expected status {expected_status}, got {status}")
        ok = False
    elif required_fields:
        data = resp.get('data', resp)
        if isinstance(data, dict):
            for f in required_fields:
                if f not in data:
                    print(f"  FAIL: {name} missing field '{f}' in response: {json.dumps(resp)[:200]}")
                    ok = False
        if forbidden_fields and isinstance(data, dict):
            for f in forbidden_fields:
                if f in data:
                    print(f"  FAIL: {name} has forbidden field '{f}' in response")
                    ok = False
    if ok:
        print(f"  PASS: {name} (status={status})")
        PASS += 1
    else:
