		return
	}
	// Validate confirmationSide
	side, _ := body["confirmationSide"].(string)
	if side != "sender" && side != "receiver" {
		h.fail(w, 400, "confirmationSide must be 'sender' or 'receiver'", "invalid_confirmation_side")
