// ── Capacity ──

func (s *Service) ConfigureCapacity(db_ *sql.DB, entityType, entityID string, cap map[string]interface{}) error {
	reg, _ := cap["capacityUnits"].(float64)
	cooled, _ := cap["cooledCapacityUnits"].(float64)
	_, err := db_.Exec(`INSERT INTO capacity (entity_type, entity_id, capacity_units, cooled_capacity_units)
		VALUES ($1, $2, $3, $4) ON CONFLICT (entity_type, entity_id) DO UPDATE SET capacity_units=$3, cooled_capacity_units=$4`,
		entityType, entityID, int(reg), int(cooled))
	return err
}

func (s *Service) GetCapacity(db_ *sql.DB, entityType, entityID string) *model.Capacity {
	var c model.Capacity
	err := db_.QueryRow(`SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM capacity WHERE entity_type=$1 AND entity_id=$2`, entityType, entityID).Scan(
		&c.CapacityUnits, &c.ReservedUnits, &c.CooledCapacityUnits, &c.CooledReservedUnits)
	if err != nil {
		return nil
	}
	c.AvailableUnits = c.CapacityUnits - c.ReservedUnits
	c.CooledAvailableUnits = c.CooledCapacityUnits - c.CooledReservedUnits
	if c.AvailableUnits < 0 {
		c.AvailableUnits = 0
	}
	return &c
}

