		var nodeID, jid, from, to sql.NullString
		rows.Scan(&aid, &sid, &status, &nodeID, &jid, &from, &to)
		plan := map[string]interface{}{
			"assignmentId": aid,
			"sampleId":     sid,
			"status":       status,
		}
		if nodeID.Valid {
			plan["nodeId"] = nodeID.String
		}
		if jid.Valid {
			plan["journeyId"] = jid.String
		}
		if from.Valid {
			plan["incomingFromLocationId"] = from.String
		}
		if to.Valid {
			plan["outgoingToLocationId"] = to.String
		}
		plans = append(plans, plan)
	}
	return plans, nil
}

// ── Laboratory Plans ──

func (s *Service) GetLaboratoryPlans(db_ *sql.DB, workerID string) ([]interface{}, error) {
	rows, err := db_.Query(`SELECT a.assignment_id, a.sample_id, a.status, a.laboratory_id,
		s.sample_type_id
		FROM assignments a JOIN samples s ON a.sample_id = s.sample_id
		WHERE a.worker_id = $1 AND a.kind = 'laboratory' ORDER BY a.created_at`, workerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var plans []interface{}
	for rows.Next() {
		var aid, sid, status string
		var labID sql.NullString
		var stID string
		rows.Scan(&aid, &sid, &status, &labID, &stID)
		plan := map[string]interface{}{
			"assignmentId":    aid,
			"sampleId":        sid,
			"status":          status,
			"expectedSampleTypeId": stID,
		}
		if labID.Valid {
			plan["laboratoryId"] = labID.String
		}
		plans = append(plans, plan)
	}
	return plans, nil
}
// ── Missing service stubs ──

func (s *Service) SetLocationFunction(db_ *sql.DB, locID, fn string, active bool) error {
	var loc model.Location
	err := db_.QueryRow(`SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations WHERE location_id=$1`, locID).Scan(
		&loc.LocationID, &loc.Name, &loc.Coordinate.Latitude, &loc.Coordinate.Longitude, &loc.CoverageKm, &loc.HandlingMinutes, &loc.Active,
		&loc.Functions.CollectionPoint, &loc.Functions.TransferPoint, &loc.Functions.Hub, &loc.Functions.Laboratory,
	)
	if err != nil {
		return fmt.Errorf("location not found: %s", locID)
	}
	q := `UPDATE locations SET fn_` + fn + ` = $1 WHERE location_id=$2`
	db_.Exec(q, active, locID)
	return nil
}

func (s *Service) UpdateSampleType(db_ *sql.DB, body map[string]interface{}) error {
stID, _ := body["sampleTypeId"].(string)
ct, _ := body["containerType"].(string)
tmin, _ := body["temperatureMinC"].(float64)
tmax, _ := body["temperatureMaxC"].(float64)
_, err := db_.Exec(`UPDATE sample_types SET container_type=$1, temperature_min_c=$2, temperature_max_c=$3 WHERE sample_type_id=$4`, ct, tmin, tmax, stID)
return err
}

func (s *Service) SetWorkerAvailability(db_ *sql.DB, workerID string, available bool, capacityUnits int) error {
_, err := db_.Exec(`UPDATE users SET available=$1, capacity_units=$2 WHERE user_id=$3`, available, capacityUnits, workerID)
return err
}

func (s *Service) UpdateAssignmentProgress(db_ *sql.DB, workerID string, body map[string]interface{}) (map[string]interface{}, error) {
aid, _ := body["assignmentId"].(string)
status, _ := body["status"].(string)
oAt, _ := body["occurredAt"].(string)
if aid == "" || status == "" {
return nil, fmt.Errorf("assignmentId and status required")
}
// Record location progress
var lat, lng float64
if coord, ok := body["coordinate"].(map[string]interface{}); ok {
lat, _ = coord["latitude"].(float64)
lng, _ = coord["longitude"].(float64)
s.RecordWorkerLocation(db_, workerID, lat, lng)
}
// Update assignment progress
db_.Exec(`INSERT INTO audit_log (actor_id, role, action, entity_type, entity_id, success, details, occurred_at) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
workerID, "worker", "progress", "assignment", aid, true, jsonify(map[string]string{"status": status, "occurredAt": oAt}), time.Now())
return map[string]interface{}{"assignmentId": aid, "status": status}, nil
}

func (s *Service) EditActivePlan(db_ *sql.DB, workerID string, body map[string]interface{}) (map[string]interface{}, error) {
jid, _ := body["journeyId"].(string)
if jid == "" {
return nil, fmt.Errorf("journeyId required")
}
s.PublishEvent("plan_edit", "journey", jid, body)
return map[string]interface{}{"journeyId": jid, "status": "edited"}, nil
}

func (s *Service) ReportDisruption(db_ *sql.DB, body map[string]interface{}) (map[string]interface{}, error) {
rType, _ := body["resourceType"].(string)
rID, _ := body["resourceId"].(string)
reason, _ := body["reason"].(string)
s.PublishEvent("disruption", rType, rID, map[string]interface{}{"reason": reason})
return map[string]interface{}{"resourceType": rType, "resourceId": rID, "status": "reported"}, nil
}

func (s *Service) RerouteJourney(db_ *sql.DB, body map[string]interface{}) (map[string]interface{}, error) {
jid, _ := body["journeyId"].(string)
reason, _ := body["reason"].(string)
if jid == "" {
return nil, fmt.Errorf("journeyId required")
}
s.PublishEvent("reroute", "journey", jid, map[string]interface{}{"reason": reason})
return map[string]interface{}{"journeyId": jid, "status": "rerouted"}, nil
}

func (s *Service) SplitJourney(db_ *sql.DB, body map[string]interface{}) (map[string]interface{}, error) {
jid, _ := body["journeyId"].(string)
sampleIDs, _ := body["sampleIds"].([]interface{})
if jid == "" {
return nil, fmt.Errorf("journeyId required")
}
newIDs := []string{}
for _, sid := range sampleIDs {
if s, ok := sid.(string); ok {
newIDs = append(newIDs, s)
}
}
s.PublishEvent("split", "journey", jid, map[string]interface{}{"sampleIds": newIDs})
return map[string]interface{}{"journeyId": jid, "newJourneyIds": newIDs, "status": "split"}, nil
}

func (s *Service) MergeJourneys(db_ *sql.DB, body map[string]interface{}) (map[string]interface{}, error) {
tid, _ := body["targetJourneyId"].(string)
sidz, _ := body["sourceJourneyIds"].([]interface{})
if tid == "" {
return nil, fmt.Errorf("journeyId required")
}
ids := []string{}
for _, x := range sidz {
if s, ok := x.(string); ok {
ids = append(ids, s)
}
}
s.PublishEvent("merge", "journey", tid, map[string]interface{}{"sourceJourneyIds": ids})
return map[string]interface{}{"journeyId": tid, "sourceJourneyIds": ids, "status": "merged"}, nil
}

func (s *Service) ReadOperationsState(db_ *sql.DB, body map[string]interface{}) (map[string]interface{}, error) {
locations, _ := s.GetLocations(db_)
connections, _ := s.GetConnections(db_)
workers, _ := s.GetWorkerLocations(db_)
return map[string]interface{}{
"samples":     []interface{}{},
"workers":     workers,
"locations":   locations,
"connections": connections,
"routes":      []interface{}{},
"handoffs":    []interface{}{},
"delays":      []interface{}{},
"exceptions":  []interface{}{},
}, nil
}

func (s *Service) ReadUIBootstrap(db_ *sql.DB, userID string) (map[string]interface{}, error) {
user, err := s.GetUser(db_, userID)
if err != nil {
return nil, err
}
locs, _ := s.GetLocations(db_)
sTypes, _ := s.GetSampleTypes(db_)
conns, _ := s.GetConnections(db_)
return map[string]interface{}{
"user":              user,
"locations":         locs,
"sampleTypes":       sTypes,
"connections":       conns,
"serviceabilityURL": "/api/read-serviceability-snapshot",
}, nil
}

func jsonify(m map[string]string) string {
b, _ := json.Marshal(m)
return string(b)
}

