func (s *Service) SearchAudit(db_ *sql.DB, params map[string]string) (*model.AuditSearchResult, error) {
	limit := 50
	offset := 0
	order := "DESC"

	where := []string{"1=1"}
	args := []interface{}{}
	i := 1

	if v, ok := params["entityType"]; ok && v != "" {
		where = append(where, fmt.Sprintf("entity_type=$%d", i))
		args = append(args, v)
		i++
	}
	if v, ok := params["entityId"]; ok && v != "" {
		where = append(where, fmt.Sprintf("entity_id=$%d", i))
		args = append(args, v)
		i++
	}
	if v, ok := params["actorId"]; ok && v != "" {
		where = append(where, fmt.Sprintf("actor_id=$%d", i))
		args = append(args, v)
		i++
	}
	if v, ok := params["action"]; ok && v != "" {
		where = append(where, fmt.Sprintf("action=$%d", i))
		args = append(args, v)
		i++
	}
	if v, ok := params["success"]; ok && v != "" {
		where = append(where, fmt.Sprintf("success=$%d", i))
		args = append(args, v == "true")
		i++
	}

	query := fmt.Sprintf(`SELECT audit_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details
		FROM audit_log WHERE %s ORDER BY occurred_at %s LIMIT %d OFFSET %d`, strings.Join(where, " AND "), order, limit, offset)

	rows, err := db_.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var entries []model.AuditEntry
	for rows.Next() {
		var a model.AuditEntry
		var details []byte
		rows.Scan(&a.AuditID, &a.ActorID, &a.Role, &a.Action, &a.EntityType, &a.EntityID, &a.Success, &a.OccurredAt, &details)
		if details != nil {
			json.Unmarshal(details, &a.Details)
		}
		if a.Details == nil {
			a.Details = map[string]interface{}{}
		}
		entries = append(entries, a)
	}

	var total int
	db_.QueryRow(fmt.Sprintf(`SELECT COUNT(*) FROM audit_log WHERE %s`, strings.Join(where, " AND ")), args...).Scan(&total)

	hasMore := offset+limit < total
	nextOffset := offset + limit
	if !hasMore {
		nextOffset = 0
	}

	return &model.AuditSearchResult{
		Entries:    entries,
		Total:      total,
		Returned:   len(entries),
		Offset:     offset,
		Limit:      limit,
		Order:      order,
		HasMore:    hasMore,
		NextOffset: &nextOffset,
	}, nil
}

