		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	jid, _ := body["journeyId"].(string)
	h.audit(r, "edit_plan", "journey", jid, true, body)
	h.ok(w, 201, result)
}

func (h *Handler) ReportDisruption(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	result, err := h.svc.ReportDisruption(h.DB, body)
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 201, result)
}

func (h *Handler) RerouteJourney(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	result, err := h.svc.RerouteJourney(h.DB, body)
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 201, result)
}

func (h *Handler) SplitJourney(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	result, err := h.svc.SplitJourney(h.DB, body)
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 201, result)
}

func (h *Handler) MergeJourneys(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	// Idempotency key is required
	if _, ok := body["idempotencyKey"].(string); !ok || body["idempotencyKey"].(string) == "" {
		h.fail(w, 400, "idempotencyKey is required", "idempotency_required")
		return
	}
	// Validate expectedPlanVersion
	pv, ok := body["expectedPlanVersion"].(float64)
	if !ok || pv < 1 {
		h.fail(w, 400, "expectedPlanVersion must be a positive integer", "invalid_plan_version")
		return
	}
	result, err := h.svc.MergeJourneys(h.DB, body)
	if err != nil {
		emsg := err.Error()
		if strings.Contains(emsg, "not found") {
			h.fail(w, 404, emsg, "not_found")
		} else {
			h.fail(w, 500, emsg, "internal_error")
		}
		return
	}
	h.ok(w, 201, result)
}

// ── Audit ──

func (h *Handler) SearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	params := map[string]string{}
	for k, v := range body {
		if s, ok := v.(string); ok {
			params[k] = s
		}
	}
	result, err := h.svc.SearchAudit(h.DB, params)
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 200, result)
}

// ── Operations State ──

func (h *Handler) ReadOperationsState(w http.ResponseWriter, r *http.Request) {
	body, _ := h.decode(r)
	state, err := h.svc.ReadOperationsState(h.DB, body)
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 200, state)
}

// ── UI Bootstrap ──

func (h *Handler) ReadUiBootstrap(w http.ResponseWriter, r *http.Request) {
	bootstrap, err := h.svc.ReadUIBootstrap(h.DB, h.uid(r))
	if err != nil {
		h.fail(w, 500, err.Error(), "internal_error")
		return
	}
	h.ok(w, 200, bootstrap)
}

// ── Events ──

func (h *Handler) StreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	events := h.svc.GetEvents(0)
	h.ok(w, 200, events)
}

// ── Readiness ──

func (h *Handler) SystemReadiness(w http.ResponseWriter, r *http.Request) {
	if err := h.DB.Ping(); err != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(503)
		json.NewEncoder(w).Encode(map[string]string{"status": "not_ready"})
		return
	}
	h.ok(w, 200, map[string]string{"status": "ready"})
}

